SELECT '22bf916a-42d5-594b-bf16-f476934a7b02', id, 'Atención ética en enfermería', 'Principios éticos, deberes deontológicos, derechos del paciente, confidencialidad, decisión libre e informada, seguridad, delegación y responsabilidad profesional.', 'REVIEW', 1, true
