SELECT 'ebeeb938-5e9d-58f2-9645-d7eb900b9adf', id, 'Función sensorial: valoración de pacientes con deficiencias auditivas', 'Valoración del adulto con deficiencia auditiva: tipos de hipoacusia, cerumen, ruido, presbiacusia, ototoxicidad, tinnitus, pérdida súbita, audiometría, dispositivos y comunicación segura.', 'REVIEW', 1, true
