ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5a8ab867-3d9c-5c51-8528-89d118017d13', 'd7bc49dd-d325-5819-b2a9-6b1797478336', 'sec_58', 'Fuente internacional', '**Organización Mundial de la Salud. Carta de Ottawa para la Promoción de la Salud.**

Uso:
- definición y áreas estratégicas de promoción.', 58)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
