ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('0353a3b8-1349-59b5-a7fd-c35d16994d75', '901df217-6496-5cb6-9645-fe24fb8e2f82', 'sec_12', 'Funcionamiento', 'Incluye las funciones corporales, actividades y participación de la persona en interacción con su entorno.', 12)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('3d5a4e19-c5a9-5f4c-bac3-efa72a82dc0e', '901df217-6496-5cb6-9645-fe24fb8e2f82', 'sec_13', 'Clave CICDE', 'Dos personas con el mismo diagnóstico pueden tener **niveles funcionales y necesidades de cuidado completamente diferentes**.

---', 13)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e8c1791d-ebca-5526-973c-8abdabe28042', '901df217-6496-5cb6-9645-fe24fb8e2f82', 'sec_14', '7. Principios del cuidado de enfermería', 'La atención debe proteger:

- dignidad;
- autonomía;
- privacidad;
- accesibilidad;
- seguridad;
- participación;
- equidad;
- independencia;
- continuidad;
- preferencias y objetivos personales.', 14)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1ade52de-7ba8-58d6-8e0b-b01f635eef21', '901df217-6496-5cb6-9645-fe24fb8e2f82', 'sec_15', 'Evitar', '- infantilizar;
- hablar solo con el acompañante;
- asumir incapacidad;
- decidir sin consultar;
- utilizar lenguaje estigmatizante;
- confundir discapacidad física con discapacidad cognitiva;
- suponer que toda persona con discapacidad está enferma.

---', 15)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
