INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('aaa2d9b7-acb9-54d0-ae7e-9336311540c7', '901df217-6496-5cb6-9645-fe24fb8e2f82', 'sec_23', '9. Actividades de la vida diaria', 'La función puede analizarse mediante:', 23)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6fb321dc-2705-5213-a55c-8d6be97c0335', '901df217-6496-5cb6-9645-fe24fb8e2f82', 'sec_24', 'Actividades básicas', '- bañarse;
- vestirse;
- alimentarse;
