INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('af223c9f-bcb2-5453-ab28-8585e93ea90f', '22c83ffa-53ce-55c3-b1ef-d0783374acab', 'sec_19', 'Entorno/social', '- vivienda;
- seguridad;
