INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f1455596-2ab9-5a4a-b2bc-14126679bc84', '6540c841-7896-562a-8253-0076318eaec0', 'sec_83', 'Fuente oncológica', '**National Cancer Institute (NCI). Cancer Treatment; Types of Cancer Treatment; Side Effects of Cancer Treatment; Infection and Neutropenia.**

