INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a7d4d99e-cf8d-53d5-9a3b-817abbdb07e0', '4e87ae0c-efb8-5267-bf04-5297f74beea5', 'sec_73', 'Diagnóstico/juicio', 'Identificar necesidades relacionadas con:
- intercambio gaseoso;
- ventilación;
- secreciones;
- tolerancia a actividad;
- ansiedad.', 73)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
