INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('790971b5-665b-591b-9bc9-8f5dcb3ce592', '4e87ae0c-efb8-5267-bf04-5297f74beea5', 'sec_78', 'Caso 1 — Saturación baja', 'Paciente con SpO₂ 84%, taquipnea y confusión.

**Prioridad:** ABC, oxígeno según protocolo y evaluación urgente.', 78)
