INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8d13101a-1b6f-585d-a929-085f52e2f875', '4e87ae0c-efb8-5267-bf04-5297f74beea5', 'sec_84', 'Caso 7 — Fatiga', 'Paciente con asma severa deja de usar músculos accesorios y se vuelve somnoliento.

