ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4cccc39a-0c6f-55fe-b98c-2f4c2aac2431', '4e87ae0c-efb8-5267-bf04-5297f74beea5', 'sec_85', 'Caso 8 — CO', 'Paciente expuesto a humo tiene cefalea y SpO₂ 99%.

**Conducta:** no descartar intoxicación por CO con oximetría convencional.', 85)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('3f2e99b3-0773-57b1-b12f-989f1dee2490', '4e87ae0c-efb8-5267-bf04-5297f74beea5', 'sec_86', 'Caso 9 — ABG', 'pH 7.28, PaCO₂ 58 mmHg.

**Interpretación inicial:** acidemia con componente respiratorio compatible con retención de CO₂.', 86)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
