ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('afd05a16-3138-592e-85ee-cb3cc3f3de15', '4e87ae0c-efb8-5267-bf04-5297f74beea5', 'sec_88', 'Caso 11 — Oximetría dudosa', 'SpO₂ 82% en mano fría y mal perfundida, paciente sin correlación clínica.

**Conducta:** verificar señal/sitio y correlacionar, sin ignorar un posible deterioro.', 88)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('78b310a9-e3cd-5156-a0a1-5d5bd8166ebe', '4e87ae0c-efb8-5267-bf04-5297f74beea5', 'sec_89', 'Caso 12 — Habla', 'Paciente solo puede decir una o dos palabras por respiración.

**Interpretación:** dificultad respiratoria significativa.

---', 89)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6a0f5e48-1f87-5aa9-a377-fb3043105c24', '4e87ae0c-efb8-5267-bf04-5297f74beea5', 'sec_90', '36. Errores frecuentes', '1. Confundir oxigenación y ventilación.
2. Pensar que SpO₂ normal descarta hipercapnia.
3. Esperar cianosis.
4. Registrar frecuencia sin contar.
5. Considerar disminución del esfuerzo siempre como mejoría.
6. Ignorar estridor.
7. Administrar oxígeno sin reevaluación.
8. Usar una meta de saturación universal para todos.
9. Confiar ciegamente en el pulsioxímetro.
10. Descartar CO por SpO₂ normal.
11. Tratar la saturación sin buscar causa.
12. Omitir nivel de conciencia.

---', 90)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f231d9a2-622a-50cc-999b-3887d2e3b9f0', '4e87ae0c-efb8-5267-bf04-5297f74beea5', 'sec_91', '37. Qué memorizar', '**Ventilación = movimiento de aire / eliminación de CO₂.**

**Perfusión = flujo sanguíneo pulmonar.**

**Difusión = movimiento de gases a través de membrana alveolocapilar.**

**V/Q = relación ventilación-perfusión.**

**Hipoxemia = O₂ bajo en sangre.**

**Hipoxia = O₂ insuficiente en tejidos.**

**Hipercapnia = CO₂ elevado.**

**SpO₂ normal no garantiza ventilación normal.**

**Estridor = vía aérea superior, prioridad.**

**Cianosis = signo tardío.**

**AARC: 94–98% mayoría que requiere O₂; 88–92% muchos pacientes con EPOC, siempre individualizar.**

---', 91)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f0d90c13-4314-51f2-bf0a-2b7839368769', '4e87ae0c-efb8-5267-bf04-5297f74beea5', 'sec_92', '38. Fuentes y validación', '', 92)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
