INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('03aff081-a4f6-5bef-bee9-f45016158249', '4e87ae0c-efb8-5267-bf04-5297f74beea5', 'sec_95', 'Oxigenoterapia', '**American Association for Respiratory Care (AARC). Clinical Practice Guideline: Management of Adult Patients With Oxygen in the Acute Care Setting. 2022.**

Uso:
- objetivos de saturación;
- monitorización;
- alto flujo;
- seguridad del oxígeno.', 95)
