INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5e3a45a5-d807-5e93-a14a-645702e59f39', '4e87ae0c-efb8-5267-bf04-5297f74beea5', 'sec_97', 'Fisiología', '**NCBI Bookshelf / StatPearls. Physiology, Pulmonary Ventilation and Perfusion.**

Uso:
