INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d95812dd-02d7-590a-8a67-1f67430ad453', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_58', 'Diagnóstico/juicio', '- obstrucción;
- limpieza ineficaz;
- ventilación inadecuada;
- riesgo de aspiración.', 58)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1be17aee-3ddf-51ef-88c5-1ac69f7eac70', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_59', 'Planificación', '- mantener permeabilidad;
- prevenir complicaciones;
- asegurar equipo.', 59)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9ff3fc84-9b7a-5d0d-bb93-a77a099f7394', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_60', 'Implementación', '- posicionamiento;
- aspiración;
- dispositivos;
- ventilación;
- cuidados de vía aérea artificial.', 60)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('472325c1-6eb0-5eba-a34e-230cf1ed0d08', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_61', 'Evaluación', '- entrada de aire;
- SpO₂;
- CO₂;
- secreciones;
- signos de fatiga;
- dispositivo.

---', 61)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('fc448720-f1d0-5dc6-84b8-b6778e23ac7b', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_62', '36. Situaciones tipo examen', '', 62)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c3000619-71e8-567f-848f-3bbcd0cc6c18', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_63', 'Caso 1 — Ronquido inconsciente', 'Paciente inconsciente ronca después de sedación.

**Prioridad:** abrir vía aérea y valorar ventilación.', 63)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d6552380-439c-5154-a571-c89ee9988319', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_64', 'Caso 2 — Gorgoteo', 'Paciente tiene sonidos de líquido y secreciones en boca.

**Conducta:** aspirar/retirar material visible según necesidad y proteger vía aérea.', 64)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('30c68f3c-0db9-55c9-9020-6ef2a8d3b8e4', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_65', 'Caso 3 — OPA consciente', 'Paciente consciente con reflejo nauseoso necesita apoyo.

**Error:** colocar OPA de rutina.', 65)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9211b2d8-6fce-5874-9664-dda82e9aa2d0', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_66', 'Caso 4 — Intubado con desaturación', 'Paciente ventilado desatura y no se puede pasar catéter de aspiración.

**Sospecha:** obstrucción/acodamiento/desplazamiento; evaluar inmediatamente.', 66)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1846c113-571a-57e3-8787-aa7b361e287e', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_67', 'Caso 5 — Tubo desplazado', 'Marca del tubo cambió 3 cm.

**Conducta:** valorar colocación y ventilación inmediatamente.', 67)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('384f9128-d589-54f5-bc9b-ea5550e5593d', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_68', 'Caso 6 — Aspiración programada', 'Orden de aspirar cada hora aunque no haya indicación.

**Principio:** AARC favorece aspiración basada en necesidad clínica.', 68)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('80030094-875a-5830-bd50-eb339224cb4c', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_69', 'Caso 7 — Salina', 'Se propone instilar rutinariamente salina antes de cada aspiración.

**Conducta:** no es recomendación rutinaria AARC.', 69)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f4d1b6c4-a105-515b-812f-2513a2be2f6f', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_70', 'Caso 8 — FBAO leve', 'Adulto tose con fuerza y puede hablar.

**Conducta:** permitir tos y observar por deterioro.', 70)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ca2340f0-f0b7-5b43-8d21-5f92a143dba6', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_71', 'Caso 9 — FBAO grave', 'Adulto consciente no puede hablar ni toser eficazmente.

**AHA 2025:** ciclos de 5 golpes dorsales y 5 compresiones abdominales.', 71)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6f566370-c5e9-57b7-8fce-bb34ffd6bdb2', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_72', 'Caso 10 — Embarazo avanzado', 'Embarazada con FBAO grave.

**AHA 2025:** 5 golpes dorsales + 5 compresiones torácicas.', 72)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('31053ac0-a217-5349-b60c-f80a15c0ad96', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_73', 'Caso 11 — Se vuelve inconsciente', 'Paciente con FBAO pierde respuesta.

**Conducta:** iniciar RCP con compresiones; retirar solo objeto visible.', 73)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e3f21746-f9f5-51f9-92e6-114ec67b7363', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_74', 'Caso 12 — Barrido ciego', 'No se ve el objeto en boca.

**Conducta:** no realizar barrido digital a ciegas.

---', 74)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8e9df5e6-e1c1-515f-9bd1-a14f81f9609d', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_75', '37. Errores frecuentes', '1. Priorizar saturación sobre una vía aérea obstruida.
2. Usar OPA en consciente.
3. Aspirar rutinariamente sin indicación.
4. Instilar salina rutinariamente.
5. Aspirar durante demasiado tiempo.
6. No preoxigenar a paciente con vía aérea artificial cuando corresponde.
7. No comprobar posición de tubo.
8. Confiar solo en auscultación tras intubación.
9. Ignorar cambio de marca del tubo.
10. No mantener humidificación.
11. Usar el algoritmo viejo de FBAO sin actualización.
12. Hacer barridos digitales a ciegas.

---', 75)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e2e07d21-6c82-5f72-b156-1e0c1137f88f', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_76', '38. Qué memorizar', '**Vía aérea primero.**

**Ronquido = posible lengua/tejido blando.**

**Gorgoteo = líquido/secreciones.**

**Estridor = obstrucción superior.**

**OPA: inconsciente sin reflejo nauseoso.**

**Aspiración artificial: según indicación, no rutina.**

**AARC: preoxigenar; evitar salina rutinaria; abierta estéril; <15 s de succión.**

**Intubación: confirmar con capnografía cuando disponible.**

**AHA 2025 FBAO grave consciente: 5 golpes dorsales + 5 abdominales.**

**Embarazo avanzado/no se puede rodear abdomen: 5 dorsales + 5 torácicas.**

**Inconsciente: RCP; retirar solo objeto visible.**

**NO barrido digital ciego.**

---', 76)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('28244fd8-f081-5eab-8233-62acbe65c6e5', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_77', '39. Fuentes y validación', '', 77)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('04337a7e-ec83-5f3c-85de-d3aeaf52f3f4', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_78', 'Fuente rectora', '**CICDE Panamá. Lineamientos para el Examen de Competencias de Profesionales de Enfermería, 2026.**', 78)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('cb9f7c35-eb3d-5ddf-bb3d-a416984de40b', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_79', 'Fuentes CICDE', '**Hinkle, J. L.; Cheever, K. H. Brunner y Suddarth. Enfermería Médicoquirúrgica. 14.ª edición, 2019.**

**Potter, P. A. et al. Fundamentos de Enfermería. 11.ª edición. Elsevier, 2023.**', 79)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('cda4bebc-5858-5940-8e3c-3d09621bb4c8', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_80', 'Vía aérea artificial', '**AARC. Clinical Practice Guidelines: Artificial Airway Suctioning. 2022.**

Uso:
- indicaciones;
- preoxigenación;
- técnica;
- salina;
- duración;
- profundidad.

**AARC. Management of Adult Patients with Tracheostomy in the Acute Care Setting. 2021.**

Uso:
- cuidado y seguridad de traqueostomía.', 80)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('79868dee-feb0-5b9d-82e8-639d51b1a3d4', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_81', 'Emergencias de vía aérea', '**American Heart Association. 2025 Guidelines for CPR and ECC — Adult Basic Life Support.**

Uso:
- FBAO leve/grave;
- actualización 5 golpes dorsales + 5 abdominales;
- embarazo avanzado;
- RCP al quedar inconsciente;
- prohibición de barrido digital ciego.

---', 81)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ae6247ec-2dda-5bb1-b0c0-b24315a10ba9', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_82', '40. Control de calidad', 'Este paquete:
- cubre reconocimiento y manejo básico/avanzado de vía aérea;
- integra aspiración basada en evidencia;
- incluye OPA/NPA, BVM, intubación, capnografía y traqueostomía;
- incorpora algoritmo AHA 2025 actualizado de FBAO;
- evita enseñar barridos digitales a ciegas;
- contiene 12 casos originales.

---', 82)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('aa205b28-e25a-5aa0-bac3-0808323b3bd7', 'eaf99e92-9f18-5362-90ff-83cc466a4615', 'sec_83', '41. Estado para integración', '**Estado recomendado:** `REVIEW`

Antes de `VERIFIED`:
- registrar `reviewed_by`;
- registrar `reviewed_at`;
- vincular fuentes;
- enlazar ADULT-13/14 y emergencias;
- mantener parámetros de cuff, ventilación y procedimientos invasivos dependientes del protocolo institucional.', 83)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c0c60cf1-e6aa-5bf6-a118-d77e6922abcb', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_1', 'Asma, neumonía, broncoaspiración y tuberculosis', '**Área:** Salud del Adulto  
**Código:** ADULT-16  
**Estado académico del paquete:** `REVIEW`  
**Última revisión del paquete:** 2026-09-10

---', 1)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('06d11c91-2662-5d32-a266-5f3a7b710f45', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_2', '1. Alcance oficial CICDE', 'El lineamiento CICDE 2026 incluye dentro de Salud del Adulto el bloque:

**Asma, Neumonía, Broncoaspiración y Tuberculosis.**

El estudiante debe integrar valoración, signos de gravedad, prioridades de enfermería, tratamiento indicado, control de infecciones, educación y prevención.

---', 2)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e873d589-f6ee-5443-8e09-793bea3e6c55', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_3', '2. ASMA', '', 3)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('cd2c3325-99d1-5c7d-b004-923097d386d5', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_4', 'Concepto', 'El asma es una enfermedad respiratoria crónica caracterizada por síntomas variables y limitación variable del flujo aéreo espiratorio, asociada con inflamación de las vías aéreas.

Síntomas frecuentes:
- sibilancias;
- disnea;
- opresión torácica;
- tos.

Pueden variar en tiempo e intensidad.', 4)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('235ec2d1-234a-553e-b273-b3ea80200fc3', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_5', 'Desencadenantes', '- infecciones virales;
- alérgenos;
- humo;
- contaminación;
- ejercicio;
- aire frío;
- algunos medicamentos;
- exposiciones ocupacionales.', 5)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d6e97745-9ee4-5333-ab0a-692eee375d0d', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_6', 'Valoración', '- frecuencia respiratoria;
- capacidad de hablar;
- uso de músculos accesorios;
- sibilancias;
- entrada de aire;
- SpO₂;
- frecuencia cardiaca;
- nivel de conciencia;
- respuesta a broncodilatador;
- flujo espiratorio máximo cuando sea apropiado.', 6)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('03e30e56-d91c-5ca1-9a82-0c1f8f149fa4', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_7', 'Signos de gravedad', '- dificultad para hablar;
- agitación o somnolencia;
- tórax silencioso;
- fatiga;
- hipoxemia;
- cianosis;
- deterioro progresivo;
- mala respuesta al tratamiento inicial.', 7)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d4a9abbb-5d5d-5b01-84cb-db77e258fc7f', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_8', 'Clave CICDE', 'Una disminución de sibilancias en un paciente que empeora puede significar **flujo de aire críticamente reducido**, no mejoría.

---', 8)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a834b4e5-95fc-5e72-9e50-a1f15a7daec3', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_9', '3. Tratamiento del asma: enfoque actual', 'GINA 2026 mantiene un principio central: los adultos y adolescentes con asma deben recibir tratamiento que incluya **corticosteroide inhalado (ICS)**; el uso de broncodilatador de rescate sin tratamiento antiinflamatorio no debe considerarse la estrategia preferida.

La selección exacta del esquema depende de:
- gravedad;
- control;
- tratamiento previo;
- disponibilidad;
- protocolo;
- evaluación médica.', 9)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('87ff8dc9-8b61-5b4f-9414-7a2794c05b22', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_10', 'Enfermería', '- verificar técnica del inhalador;
- evaluar adherencia;
- identificar desencadenantes;
- vigilar respuesta;
- educar sobre plan de acción;
- enseñar cuándo buscar atención urgente.', 10)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('fc042194-6550-5beb-811a-9307825cc314', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_11', 'Copyright', 'GINA 2026 es una fuente protegida. La plataforma no debe copiar extensamente tablas o algoritmos propietarios; debe resumir conceptos y enlazar la fuente.

---', 11)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('27090a65-52b1-56b7-b7d6-20deef1be6c3', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_12', '4. Exacerbación asmática', 'Prioridades:
1. valorar ABC;
2. sentar/incorporar;
3. administrar oxígeno si está indicado;
4. broncodilatador de acción rápida según prescripción/protocolo;
5. corticosteroide sistémico cuando esté indicado;
6. monitorizar respuesta;
7. escalar si no mejora.', 12)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('37e9f4ab-1fc0-5e94-80d7-0ce2ac72f255', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_13', 'Alarma', 'Paciente exhausto, somnoliento, con entrada de aire mínima o deterioro de gases arteriales requiere evaluación avanzada urgente.

---', 13)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f40267e9-3ec6-5986-8db8-7979430ca898', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_14', '5. NEUMONÍA', '', 14)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('36eab28f-c5f0-52c0-81d3-571184b72ebd', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_15', 'Concepto', 'La neumonía es una infección del parénquima pulmonar.

Puede clasificarse según contexto:
- adquirida en la comunidad;
- hospitalaria;
- asociada a ventilación;
- relacionada con aspiración.', 15)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('45cc3c73-acf9-5877-aed4-47bcb362b14b', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_16', 'Manifestaciones posibles', '- fiebre;
- tos;
- expectoración;
- disnea;
- dolor torácico pleurítico;
- taquipnea;
- crepitantes;
- hipoxemia;
- debilidad.

En adultos mayores puede presentarse con:
- confusión;
- deterioro funcional;
- menor apetito;
- caídas;
- menor respuesta febril.

---', 16)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1c4958df-c5dc-53ea-a072-6ca07e12ab03', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_17', '6. Valoración de neumonía', '- signos vitales;
- SpO₂;
- trabajo respiratorio;
- conciencia;
- hidratación;
- tos y secreciones;
- dolor;
- comorbilidades;
- edad;
- capacidad funcional;
- estudios indicados.

La radiografía de tórax suele formar parte de la confirmación diagnóstica en pacientes hospitalizados o cuando existe duda clínica.

---', 17)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('421cb462-af17-56cc-aaa6-e001943bce22', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_18', '7. Tratamiento de neumonía', 'La guía ATS/IDSA vigente para neumonía adquirida en la comunidad adulta sigue siendo la publicada en 2019.

El tratamiento antibiótico depende de:
- lugar de adquisición;
- gravedad;
- comorbilidades;
- exposición previa a antibióticos;
- riesgo de microorganismos resistentes;
- alergias;
- función renal/hepática;
- epidemiología local.', 18)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9bc17339-4884-50d5-bf79-d0d2b37cb368', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_19', 'Enfermería', '- administrar antibióticos prescritos oportunamente;
- obtener cultivos cuando estén indicados y sin retrasar tratamiento crítico;
- oxígeno según necesidad;
- hidratación individualizada;
- movilización;
- control de fiebre/dolor;
- vigilancia de sepsis;
- educación.

---', 19)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5ac9c33d-31ce-553a-ba37-d7752064c419', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_20', '8. Complicaciones de neumonía', '- insuficiencia respiratoria;
- sepsis;
- derrame pleural;
- empiema;
- absceso pulmonar;
- descompensación de enfermedades crónicas.', 20)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9c9be865-ee98-5408-b7f9-3eb07334b2ac', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_21', 'Signos de deterioro', '- aumento de trabajo respiratorio;
- hipotensión;
- confusión;
- oliguria;
- hipoxemia;
- lactato elevado cuando se mide;
- empeoramiento clínico.

---', 21)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('07f9dee9-538f-5637-a8a2-f0f8fc7dd3fb', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_22', '9. BRONCOASPIRACIÓN', '', 22)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ee11f91e-22eb-5db5-890e-ee1053435a66', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_23', 'Concepto', 'La aspiración puede producir:
- obstrucción de vía aérea;
- neumonitis química;
- neumonía bacteriana;
- absceso pulmonar.

No toda aspiración produce infección.

---', 23)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2e929744-0bb7-513d-adb0-1174b48d58a2', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_24', '10. Factores de riesgo de aspiración', '- disminución de conciencia;
- sedación;
- intoxicación;
- convulsiones;
- disfagia;
- ACV;
- enfermedad neurológica;
- vómitos;
- alimentación por sonda;
- procedimientos;
- mala protección de vía aérea.

---', 24)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4986cf89-3350-5a5b-8cca-690e8b9d81db', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_25', '11. Neumonitis aspirativa vs neumonía aspirativa', '', 25)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('38c9e51a-7f58-5ff2-884d-d33d05e67c0a', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_26', 'Neumonitis aspirativa', 'Lesión inflamatoria química, frecuentemente por contenido gástrico.

Tratamiento inicial suele ser principalmente:
- soporte;
- oxigenación;
- ventilación si es necesaria;
- vigilancia.', 26)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('14c786f9-1f22-529b-b79d-a4f67e80be2b', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_27', 'Neumonía aspirativa', 'Infección bacteriana tras aspiración en un paciente con defensas de vía aérea alteradas.

Puede requerir antibióticos.', 27)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4756bbf3-8f24-5b2a-a0ae-ec2c323c590c', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_28', 'Clave CICDE', '**Aspiración presenciada no significa automáticamente antibióticos profilácticos.** Se debe valorar el cuadro clínico.

---', 28)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2390350a-1467-5e97-94cd-468f3de1e5b2', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_29', '12. Prevención de aspiración', '- valorar nivel de conciencia;
- cabecera elevada cuando corresponda;
- verificar capacidad deglutoria;
- higiene oral;
- posición segura durante alimentación;
- alimentación lenta;
- seguir recomendaciones de textura;
- suspender vía oral si existe riesgo importante hasta evaluación;
- controlar náuseas/vómitos;
- vigilar sondas y dispositivos.', 29)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('edb61202-ae1a-5891-b6ed-ced67ba51cb8', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_30', 'Importante', 'Una sonda de alimentación **no elimina totalmente el riesgo de aspiración**.

---', 30)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('87069b57-0a8f-5dc8-8907-644596857d8c', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_31', '13. Disfagia', 'Signos:
- tos al comer/beber;
- atragantamiento;
- voz húmeda;
- residuos en boca;
- múltiples degluciones;
- pérdida de peso;
- neumonías recurrentes.

Conducta:
- detener alimentación si existe riesgo inmediato;
- posicionar;
- valorar vía aérea;
- solicitar evaluación de deglución;
- aplicar plan individualizado.

---', 31)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b8d8a389-086e-56b5-a417-5dff3c914d9e', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_32', '14. TUBERCULOSIS', '', 32)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('144b6e3e-7266-56bc-b79e-40e5cd75560d', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_33', 'Concepto', 'La tuberculosis (TB) es una enfermedad infecciosa causada por *Mycobacterium tuberculosis*, que afecta con mayor frecuencia los pulmones.

La OMS, en su actualización del 24 de marzo de 2026, señala que:
- es prevenible y curable;
- se transmite por el aire;
- la infección latente/inactiva no equivale a enfermedad activa;
- las personas con TB pulmonar activa pueden transmitirla.

---', 33)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c3cc94b4-29f5-5285-90ee-b4bb3bcfd690', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_34', '15. Factores de riesgo de desarrollar enfermedad TB', 'Entre otros:
- VIH/inmunosupresión;
- desnutrición;
- diabetes;
- consumo de tabaco;
- consumo nocivo de alcohol;
- exposición cercana;
- condiciones de hacinamiento.

---', 34)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('78a1100d-c989-5612-82ce-5f80b2b09346', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_35', '16. Manifestaciones de TB pulmonar', 'Pueden incluir:
- tos persistente;
- expectoración;
- hemoptisis;
- fiebre;
- sudoración nocturna;
- pérdida de peso;
- anorexia;
- fatiga.

No todos los pacientes presentan todos los síntomas.

---', 35)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('50879f01-f0af-52d3-83f6-4b69c1d81805', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_36', '17. Diagnóstico', 'Puede incluir:
- pruebas moleculares rápidas;
- baciloscopia;
- cultivo;
- radiografía;
- pruebas de sensibilidad;
- evaluación clínica.

La OMS prioriza pruebas moleculares rápidas como herramientas diagnósticas iniciales en muchos contextos.

---', 36)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c3eea74a-1f77-5eaa-8f15-8b597267d86e', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_37', '18. Precauciones por transmisión aérea', 'En sospecha o confirmación de TB pulmonar/laríngea infecciosa:

- iniciar **precauciones aéreas**;
- habitación de aislamiento respiratorio con presión negativa cuando esté disponible;
- personal con respirador N95 o superior apropiadamente ajustado;
- paciente con mascarilla quirúrgica durante transporte;
- limitar traslados no esenciales;
- higiene respiratoria.', 37)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4a656707-b899-541a-bdb5-dadb124c1922', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_38', 'Clave', 'La mascarilla quirúrgica del paciente es **control de fuente**.  
El respirador N95 del personal es **protección respiratoria**.

---', 38)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('84e39e04-61e2-5613-a278-8854fa6435af', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_39', '19. Tratamiento de TB', 'La TB sensible suele requerir tratamiento combinado con varios fármacos durante meses.

La elección del régimen depende de:
- susceptibilidad;
- localización;
- edad;
- embarazo;
- función hepática/renal;
- VIH;
- resistencias;
- guías nacionales.', 39)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5e3964b1-579e-5fed-8cc8-0e231c155ba2', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_40', 'Seguridad', 'No se incluirán dosis universales en esta lección.

---', 40)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7d0fdaeb-f7ec-5e9e-9597-4a6ba4423643', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_41', '20. Medicamentos antituberculosos: vigilancia de enfermería', 'Fármacos clásicos de primera línea pueden incluir:
- isoniazida;
- rifampicina/rifampina;
- pirazinamida;
- etambutol.

Aspectos a vigilar:
- hepatotoxicidad;
- interacciones;
- adherencia;
- alteraciones visuales con etambutol;
- neuropatía periférica asociada a isoniazida;
- cambios de color de fluidos corporales con rifampicina;
- toxicidades específicas.

Cualquier síntoma significativo debe comunicarse según protocolo.

---', 41)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('dff24efb-cfb1-52bf-8088-8e22961c78fb', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_42', '21. Adherencia y TAES/DOTS', 'El Programa de Control de la Tuberculosis de MINSA Panamá mantiene entre sus funciones garantizar acceso a detección, diagnóstico, tratamiento y control, y hace referencia a la estrategia **TAES** (tratamiento acortado estrictamente supervisado).

Objetivos:
- curar al paciente;
- reducir transmisión;
- prevenir resistencia;
- evitar abandono.

---', 42)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('0de8b85e-8160-5ddb-b1fa-4182b2b136fa', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_43', '22. Contexto Panamá', 'La página vigente del Programa de Control de la Tuberculosis de MINSA publica como documentos relacionados:

- Norma Técnica Nacional para el Control de la Tuberculosis en Panamá, Resolución 235 de 17 de abril de 2017;
- Norma para el manejo clínico del paciente con tuberculosis drogorresistente;
- boletines y estadísticas recientes.', 43)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7255c86b-c700-58d7-af0f-3030a7e5e661', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_44', 'Regla de gobernanza', 'Antes de marcar este módulo `VERIFIED`, se debe comprobar si alguna resolución posterior sustituyó formalmente la norma 2017. La página actual del programa todavía la publica, pero la plataforma no debe asumir por eso que no existe ninguna actualización complementaria.

---', 44)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('135217a8-2ab8-55c5-ad33-8a00f9f113aa', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_45', '23. Educación en TB', '- explicar transmisión aérea;
- adherencia estricta;
- higiene respiratoria;
- ventilación;
- uso de mascarilla cuando corresponda;
- evitar abandono;
- reconocer efectos adversos;
- acudir a controles;
- estudio de contactos conforme al programa;
- combatir estigma.

---', 45)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6a56b85a-5c34-5efe-a1ed-3cb5e1aa770e', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_46', '24. PAE integrado', '', 46)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('16b236ad-742f-5a17-b250-73dd4899f8b8', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_47', 'Valoración', '- vía aérea;
- respiración;
- SpO₂;
- secreciones;
- fiebre;
- conciencia;
- factores de riesgo;
- adherencia;
- exposición.', 47)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('3ef81b65-d16d-5cac-b724-798fc9959de3', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_48', 'Diagnóstico/juicio', 'Identificar:
- intercambio gaseoso;
- limpieza de vía aérea;
- riesgo de aspiración;
- infección/transmisión;
- conocimiento/autocuidado.', 48)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('77152ce1-ef88-5977-abd4-da326efd6c13', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_49', 'Planificación', '- oxigenación;
- permeabilidad;
- control de infección;
- tratamiento seguro;
- educación.', 49)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9b8d8fbe-2e6d-5257-a9ed-d743ea11dbe5', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_50', 'Implementación', '- administrar terapias prescritas;
- aislamiento;
- higiene;
- posicionamiento;
- monitorización;
- educación.', 50)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1246eaf4-ed6a-578d-98bf-bab101609245', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_51', 'Evaluación', '- trabajo respiratorio;
- SpO₂;
- síntomas;
- respuesta;
- adherencia;
- signos de complicación.

---', 51)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('3d9faab1-3b87-5a21-a5dd-f8440e0184e6', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_52', '25. Situaciones tipo examen', '', 52)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7365367d-3a98-51bf-8c79-7562826b66fc', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_53', 'Caso 1 — Asma que “deja de silbar”', 'Paciente con asma grave inicialmente sibilante se vuelve somnoliento y casi no se ausculta entrada de aire.

**Prioridad:** deterioro crítico, posible agotamiento; no asumir mejoría.', 53)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('61ca7968-32dd-58d7-955e-769176247a0a', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_54', 'Caso 2 — Inhalador', 'Paciente usa inhalador de rescate con frecuencia pero no conoce su tratamiento controlador.

**Conducta:** revisar control, técnica, adherencia y plan antiinflamatorio indicado.', 54)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('df81d4d1-54d8-50f2-9488-db6159b86229', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_55', 'Caso 3 — Neumonía en adulto mayor', 'Persona mayor llega confusa y débil sin fiebre alta.

**Conducta:** no descartar neumonía; valorar respiración, oxigenación e infección.', 55)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('04dadc97-c2cb-574b-9230-8e7b84fa365a', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_56', 'Caso 4 — Sepsis', 'Paciente con neumonía presenta hipotensión, confusión y oliguria.

**Prioridad:** sospechar deterioro sistémico/sepsis y escalar urgentemente.', 56)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d6622b14-11e2-585c-b285-b1685697ba80', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_57', 'Caso 5 — Aspiración', 'Paciente vomita y aspira contenido gástrico, luego presenta disnea aguda.

**Conducta:** ABC, oxígeno/soporte y vigilancia; antibiótico no es automático por el solo evento.', 57)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d86842f4-9d7e-5c1b-b535-d4cc695ed449', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_58', 'Caso 6 — Disfagia', 'Paciente post-ACV tose con cada sorbo.

**Conducta:** detener vía oral no segura y solicitar evaluación de deglución.', 58)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('83137602-ea62-533d-9cbf-caae5b1986b2', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_59', 'Caso 7 — TB sospechada', 'Paciente con tos crónica, pérdida de peso y hemoptisis llega a urgencias.

**Conducta:** control de fuente + precauciones aéreas tempranas.', 59)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f7d73e7b-acf4-5ccc-864d-a8d1a3a536ca', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_60', 'Caso 8 — Transporte TB', 'Paciente con TB infecciosa requiere radiografía.

**Conducta:** limitar traslado a lo necesario y colocar mascarilla quirúrgica al paciente.', 60)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('66710488-c557-5f5a-8c52-ce5408727736', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_61', 'Caso 9 — Personal', 'Enfermera entra a habitación de aislamiento TB.

**Protección:** respirador N95 o superior, ajustado conforme al programa institucional.', 61)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d67ac00c-56f2-58df-a394-5552186ebaa4', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_62', 'Caso 10 — TB latente', 'Persona con infección TB inactiva está asintomática.

**Concepto:** no se considera contagiosa como una persona con TB pulmonar activa.', 62)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a10dbaa6-cbea-5410-ac6c-c6698400678c', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_63', 'Caso 11 — Etambutol', 'Paciente informa cambios visuales durante tratamiento.

**Conducta:** comunicar de forma oportuna y seguir protocolo.', 63)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2fad4336-ab96-5c8f-b9f1-f80f0d2b9c1f', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_64', 'Caso 12 — Abandono de TB', 'Paciente quiere suspender tratamiento porque se siente mejor.

**Conducta:** educación y coordinación con programa; el abandono favorece recaída, transmisión y resistencia.

---', 64)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('20456290-2dd6-55aa-9b18-afb1c05c057d', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_65', '26. Errores frecuentes', '1. Interpretar ausencia de sibilancias como mejoría en asma grave.
2. Depender solo del SABA sin abordar tratamiento controlador.
3. Normalizar confusión en adulto mayor con neumonía.
4. No valorar sepsis.
5. Dar antibiótico automáticamente a toda aspiración química.
6. Continuar alimentación en disfagia evidente.
7. Creer que una sonda elimina riesgo de aspiración.
8. Usar precauciones de gotas en lugar de aéreas para TB pulmonar infecciosa.
9. Poner N95 al paciente y mascarilla quirúrgica al trabajador como estrategia estándar.
10. Confundir infección TB con enfermedad TB.
11. Suspender tratamiento porque desaparecen síntomas.
12. Ignorar efectos adversos de antituberculosos.

---', 65)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('84fd8f5c-167e-5e7c-aa01-1c7f696aa980', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_66', '27. Qué memorizar', '**Asma grave + silencio pulmonar/somnolencia = emergencia.**

**GINA 2026: tratamiento del adulto debe incluir componente antiinflamatorio con ICS.**

**Neumonía: valorar oxigenación + gravedad + sepsis.**

**Aspiración química ≠ neumonía bacteriana automática.**

**Disfagia + tos con alimentación = riesgo de aspiración.**

**TB pulmonar infecciosa = transmisión aérea.**

**TB: paciente con mascarilla quirúrgica para control de fuente; personal con N95 o superior.**

**TB latente/inactiva no transmite como enfermedad pulmonar activa.**

**Adherencia al tratamiento TB es crítica.**

---', 66)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('fbc4085d-2f1d-5c82-9897-ec41b5073589', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_67', '28. Fuentes y validación', '', 67)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f97a3f72-65c8-5a95-9188-4c1e2a9d0980', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_68', 'Fuente rectora', '**CICDE Panamá. Lineamientos para el Examen de Competencias de Profesionales de Enfermería, 2026.**', 68)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('98454071-d28a-5581-916f-3d26030f3897', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_69', 'Fuentes CICDE', '**Hinkle, J. L.; Cheever, K. H. Brunner y Suddarth. Enfermería Médicoquirúrgica. 14.ª edición, 2019.**

**Potter, P. A. et al. Fundamentos de Enfermería. 11.ª edición, 2023.**', 69)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('706dd397-f37a-5201-a9b4-7afa824f51ba', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_70', 'Asma', '**Global Initiative for Asthma (GINA). Global Strategy for Asthma Management and Prevention, 2026.**

Uso:
- concepto;
- tratamiento con ICS;
- evaluación de control y exacerbación.', 70)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7c03f18d-22a9-594e-b325-c71314e748a8', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_71', 'Neumonía', '**ATS/IDSA. Diagnosis and Treatment of Adults with Community-Acquired Pneumonia. Guideline vigente, 2019.**', 71)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4fea8fe8-4c6e-56d6-b27a-d216f32bf3b6', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_72', 'Broncoaspiración', '**Merck Manual Professional Edition. Aspiration Pneumonitis and Pneumonia. Revisión 2024.**', 72)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ec452220-2caf-5d7b-837c-ef7283d07188', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_73', 'Tuberculosis', '**OMS. Tuberculosis. Hoja informativa actualizada 24 de marzo de 2026.**

**CDC. Tuberculosis Infection Control / Airborne Precautions.**

**MINSA Panamá. Programa de Control de la Tuberculosis.**

---', 73)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8009c0f7-bdc5-5d6f-95f3-a73b4c836354', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_74', '29. Control de calidad', 'Este paquete:
- cubre los cuatro subtemas expresos del CICDE;
- utiliza GINA 2026;
- distingue neumonitis aspirativa de neumonía aspirativa;
- incluye control de transmisión aérea de TB;
- integra el programa MINSA Panamá;
- no fija dosis antibióticas/antituberculosas universales;
- contiene 12 casos originales.

---', 74)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9811e374-2d05-5050-80ec-c268bae24fc7', 'a185294c-1efc-5208-8bea-c0fce4219a88', 'sec_75', '30. Estado para integración', '**Estado recomendado:** `REVIEW`

Antes de `VERIFIED`:
- registrar `reviewed_by` y `reviewed_at`;
- vincular fuentes;
- confirmar actualización formal de normativa TB Panamá;
- enlazar con ADULT-13, ADULT-14, ADULT-15 y Salud Pública.', 75)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('402cee5f-6d94-554c-bd6c-7b15b6969076', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_1', 'Función cardiovascular y circulatoria', '**Área:** Salud del Adulto  
**Código:** ADULT-17  
**Estado académico del paquete:** `REVIEW`  
**Última revisión del paquete:** 2026-09-10

---', 1)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1305d0b2-beb4-59cf-8ea6-ff160ff03d7e', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_2', '1. Alcance oficial CICDE', 'El lineamiento CICDE 2026 incluye dentro de función cardiovascular/circulatoria:

- angina y arritmias;
- edema pulmonar;
- paro cardiorrespiratorio;
- embolia y trombosis;
- aneurisma;
- hipertensión arterial, crisis y valoración.

Este es uno de los bloques más amplios de Salud del Adulto y requiere fuerte dominio de **prioridades y reconocimiento temprano del deterioro**.

---', 2)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7e61e98e-e7a3-5bd5-89b2-f3c682fedb7e', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_3', '2. Objetivos', 'El estudiante debe poder:

1. Realizar valoración cardiovascular básica.
2. Reconocer isquemia miocárdica y síndrome coronario agudo.
3. Diferenciar arritmia estable e inestable.
4. Reconocer ritmos de paro.
5. Aplicar principios BLS/ALS AHA 2025.
6. Reconocer edema pulmonar cardiogénico.
7. Identificar TVP y embolia pulmonar.
8. Reconocer signos de aneurisma complicado/ruptura.
9. Medir e interpretar presión arterial correctamente.
10. Diferenciar hipertensión severa sin daño agudo de órgano de emergencia hipertensiva.
11. Aplicar seguridad farmacológica y vigilancia.
12. Integrar PAE y casos clínicos.

---', 3)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('40378d3b-c112-54c6-adba-0815bc981112', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_4', '3. Valoración cardiovascular', '', 4)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6f992894-1baa-5b37-821f-1669d85dd2ee', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_5', 'Historia', '- dolor torácico;
- disnea;
- palpitaciones;
- síncope/presíncope;
- edema;
- fatiga;
- intolerancia al esfuerzo;
- claudicación;
- antecedentes cardiovasculares;
- factores de riesgo;
- medicamentos.', 5)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('cfda369b-f673-5898-8a9a-c804797b1c46', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_6', 'Examen', '- presión arterial;
- pulso/frecuencia/ritmo;
- perfusión;
- temperatura/color de piel;
- relleno capilar;
- pulsos periféricos;
- edema;
- yugulares;
- auscultación cardiaca/pulmonar;
- estado mental;
- diuresis.

---', 6)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('86b16dad-20a3-58e0-9657-befd7cfd2309', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_7', '4. Perfusión y gasto cardiaco', '**Gasto cardiaco = frecuencia cardiaca × volumen sistólico**

La perfusión puede deteriorarse por:
- frecuencia excesivamente rápida/lenta;
- falla de bomba;
- hipovolemia;
- obstrucción;
- arritmia;
- vasodilatación extrema.

Signos:
- hipotensión;
- alteración mental;
- piel fría;
- oliguria;
- dolor torácico;
- disnea;
- síncope.

---', 7)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('99b302f5-dd46-5599-ad6b-f4dcf20a5c6e', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_8', '5. Dolor torácico e isquemia', 'La angina es dolor/molestia relacionada con isquemia miocárdica.

Puede presentarse como:
- presión;
- opresión;
- peso;
- ardor;
- malestar.

Puede irradiar a:
- brazo;
- hombro;
- mandíbula;
- cuello;
- espalda;
- epigastrio.

También puede manifestarse con:
- disnea;
- náuseas;
- diaforesis;
- fatiga;
- mareo.', 8)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('fbd29530-7ac2-5f7f-9c8b-040ce61915f5', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_9', 'Clave', 'No todos los síndromes coronarios se presentan con dolor torácico “típico”.

---', 9)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e5ad12b8-1d8e-50b8-929b-b4be097c2a4b', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_10', '6. Síndrome coronario agudo (SCA)', 'Incluye:
- angina inestable;
- NSTEMI;
- STEMI.

La guía ACC/AHA 2025 actualizó el manejo de SCA y enfatiza evaluación rápida, terapias antitrombóticas apropiadas y estrategias de reperfusión/invasivas según el caso.', 10)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ec49aeae-1b79-556b-bf57-e6d9a44aaca4', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_11', 'Prioridades de enfermería', '- ABC;
- ECG rápido;
- signos vitales;
- monitor cardiaco;
- acceso IV;
- valorar dolor;
- obtener troponina y estudios indicados;
- administrar tratamientos prescritos;
- detectar shock/arritmias.

---', 11)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8c8dc095-496d-5ecc-86f8-1715f14d4335', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_12', '7. ECG y troponina', '', 12)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c7eae081-b84a-5a8a-ba1f-33f954b1f945', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_13', 'ECG de 12 derivaciones', 'Es esencial en evaluación de posible SCA.

Debe obtenerse con rapidez según protocolos de dolor torácico.', 13)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('03d187ff-be81-5559-b98c-7e255388ac18', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_14', 'Troponina cardiaca', 'Es biomarcador principal de lesión miocárdica.', 14)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('89acb302-9207-50ff-9dba-4b7864c13264', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_15', 'Importante', 'Troponina elevada indica lesión miocárdica, pero la interpretación de infarto requiere contexto clínico, evolución y ECG.

---', 15)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6f4a2221-851a-598e-94e9-4d6b20c797f5', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_16', '8. Oxígeno en SCA', 'No se utiliza automáticamente solo porque exista dolor torácico.

Se administra cuando:
- hay hipoxemia;
- dificultad respiratoria;
- otra indicación clínica.

La hiperoxia innecesaria no aporta beneficio rutinario.

---', 16)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('0fb41a8f-c4c1-56ee-9eaa-164ee37221bb', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_17', '9. Nitroglicerina', 'Puede utilizarse en isquemia/angina conforme a prescripción.

Antes:
- presión arterial;
- uso reciente de inhibidores PDE-5;
- sospecha de infarto de ventrículo derecho;
- otros factores de riesgo.

Efectos:
- cefalea;
- hipotensión;
- mareo.', 17)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('61076462-9caa-5d36-a5f3-89d6344c0543', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_18', 'Seguridad', 'No administrar automáticamente sin valorar hemodinamia y contraindicaciones.

---', 18)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('27e2f6cf-87ec-571d-9dab-ca83a9dbf25d', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_19', '10. Antiagregación y anticoagulación', 'En SCA pueden utilizarse:
- aspirina;
- inhibidores P2Y12;
- anticoagulantes.

La selección depende del escenario y riesgo.', 19)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8109e1fd-28e5-57d9-bffb-3fe8d87f5492', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_20', 'Enfermería', '- valorar sangrado;
- alergias;
- antecedentes;
- administrar según orden;
- vigilar complicaciones.

---', 20)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ad7f7221-3e20-55bc-a9d6-5526c231ecd7', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_21', '11. Arritmias: principio general', 'Una arritmia se interpreta según:
- frecuencia;
- ritmo;
- QRS;
- relación P-QRS;
- síntomas;
- perfusión;
- estabilidad.', 21)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e61e4f85-7313-5f55-af0a-9390961eb439', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_22', 'Inestabilidad', 'Signos importantes:
- hipotensión;
- alteración aguda de conciencia;
- signos de shock;
- dolor isquémico;
- insuficiencia cardiaca aguda.

La misma frecuencia puede ser tolerada por un paciente y peligrosa para otro.

---', 22)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a346f6b8-4995-5976-9f29-f9ad97282eff', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_23', '12. Bradicardia sintomática', 'Bradicardia clínicamente significativa puede producir:
- hipotensión;
- síncope;
- alteración mental;
- dolor isquémico;
- shock;
- insuficiencia cardiaca.

El manejo AHA 2025 puede incluir:
- corrección de causa;
- atropina cuando indicada;
- marcapasos transcutáneo;
- infusiones vasoactivas;
- escalamiento.

No toda bradicardia requiere tratamiento si el paciente está estable y asintomático.

---', 23)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('55d3e498-640c-54d9-a414-1aac94066969', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_24', '13. Taquicardia con pulso', 'Primero determinar:
- estabilidad;
- QRS estrecho/ancho;
- regularidad.', 24)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7b364f14-a267-5ee3-9a04-9df81777f64e', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_25', 'Inestable', 'La cardioversión sincronizada es una intervención central cuando la taquiarritmia causa inestabilidad.', 25)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('77eb107c-9304-5bb2-98a6-323ab153364e', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_26', 'Estable', 'Puede permitir:
- maniobras vagales;
- medicamentos específicos;
- evaluación del ritmo.

El tratamiento depende del tipo de arritmia.

---', 26)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('0cf65e38-8004-5ae5-b21a-86227d4d26d3', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_27', '14. Fibrilación auricular', 'FA es una arritmia supraventricular irregular.

Riesgos:
- respuesta ventricular rápida;
- deterioro hemodinámico;
- tromboembolismo/ACV.

La guía ACC/AHA 2023 enfatiza:
- control de factores de riesgo;
- evaluación de riesgo tromboembólico;
- anticoagulación cuando corresponde;
- control de frecuencia/ritmo individualizado.', 27)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6ebf62e8-b472-52c6-a88d-87ff23b52d76', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_28', 'Clave', 'Aspirina **no es sustituto equivalente de anticoagulación** cuando ésta está indicada por riesgo tromboembólico.

---', 28)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e7f4cf57-31e9-5817-8162-fc001d3c73e9', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_29', '15. Taquicardia ventricular', 'Puede presentarse con o sin pulso.', 29)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9d232501-1514-55ca-91f0-7b796a9d675d', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_30', 'Con pulso', 'Valorar estabilidad.', 30)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('98f3e9db-f040-52c6-9037-28254854c571', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_31', 'Sin pulso', 'Se maneja como ritmo desfibrilable de paro.

---', 31)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b422d6a6-0098-59e7-b7f0-d50dd0c35dd0', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_32', '16. Fibrilación ventricular', 'Ritmo caótico sin gasto cardiaco efectivo.

Tratamiento:
- RCP de alta calidad;
- desfibrilación rápida;
- algoritmo ALS.

---', 32)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('bf393370-3ae6-584a-bb35-078d15942189', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_33', '17. Asistolia y actividad eléctrica sin pulso (AESP)', 'Son ritmos **no desfibrilables**.

Manejo:
- RCP;
- epinefrina;
- búsqueda de causas reversibles.', 33)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a9381f48-bb86-5d58-a66d-d609bb41d60f', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_34', 'Error grave', 'Intentar desfibrilar una asistolia real.

---', 34)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2687c83e-f567-5349-a5b0-1b8d51136783', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_35', '18. Paro cardiorrespiratorio — reconocimiento', 'Adulto:
- no responde;
- no respira normalmente o solo jadea;
- profesional sanitario no detecta pulso definido rápidamente.

Activar sistema de respuesta y comenzar RCP.

---', 35)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('759112df-9e90-5ff6-858b-7c5ecb803f70', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_36', '19. RCP de alta calidad — AHA 2025', 'Para adulto:
- frecuencia **100–120 compresiones/min**;
- profundidad al menos **5 cm**, evitando >6 cm;
- permitir retroceso completo;
- minimizar interrupciones;
- evitar ventilación excesiva.

Sin vía aérea avanzada:
- relación habitual 30:2.

Con vía aérea avanzada:
- compresiones continuas y ventilación según algoritmo vigente.

---', 36)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b8ab9da1-3d16-5250-ab44-d8738584c7d3', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_37', '20. Desfibrilación', 'Ritmos desfibrilables:
- FV;
- TV sin pulso.

Prioridades:
- desfibrilación temprana;
- RCP inmediata entre análisis/choques;
- minimizar pausa peri-choque.

---', 37)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f6a266d1-f451-5521-a118-199d2a90dbd1', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_38', '21. Epinefrina en paro — AHA 2025', 'AHA 2025 recomienda epinefrina en paro cardiaco adulto.

Dosis estándar ALS:
**1 mg IV/IO cada 3–5 minutos.**

Timing:
- ritmos no desfibrilables: tan pronto como sea factible;
- ritmos desfibrilables: después de intentos iniciales de desfibrilación fallidos.', 38)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e64b388c-a85a-5b66-9ca0-2b78f4fa47d8', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_39', 'Gobernanza', 'Las dosis de reanimación pueden incluirse porque forman parte de un algoritmo internacional estandarizado, pero la plataforma debe vincular la versión AHA 2025.

---', 39)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5ceb95b4-dbc9-5aa6-aade-dd3fcb42c164', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_40', '22. Antiarrítmicos en paro', 'Para FV/TV sin pulso refractaria a desfibrilación:
- amiodarona o lidocaína pueden considerarse según AHA 2025.

No se recomienda de rutina durante paro:
- calcio;
- bicarbonato;
- magnesio;

salvo circunstancias específicas.

---', 40)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f62621e2-535d-584f-9179-9d593b3ee8ea', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_41', '23. Causas reversibles del paro', 'Recordar **H y T**:

- hipovolemia;
- hipoxia;
- hidrogeniones/acidosis;
- hipo/hiperpotasemia y alteraciones metabólicas;
- hipotermia;
- neumotórax a tensión;
- taponamiento cardiaco;
- toxinas;
- trombosis pulmonar;
- trombosis coronaria.

---', 41)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e9ada2ec-b3e5-59f8-9ac6-dd7748842dd6', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_42', '24. Retorno de circulación espontánea (ROSC)', 'Después de ROSC:
- asegurar vía aérea/ventilación;
- evitar hipoxemia e hiperoxia;
- sostener presión/perfusión;
- ECG;
- identificar causa;
- control de temperatura según indicación;
- cuidados neurológicos;
- traslado a nivel adecuado.

AHA publicó guía específica de cuidados post-paro en 2025.

---', 42)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('990d812e-dca7-5ba6-926d-2a32c9432c67', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_43', '25. Edema pulmonar cardiogénico', 'Merck 2025 lo describe como inundación alveolar aguda por aumento de presión venosa pulmonar debido a insuficiencia ventricular izquierda grave.

Manifestaciones:
- disnea severa;
- ansiedad;
- diaforesis;
- crepitantes;
- sibilancias;
- posible esputo espumoso rosado;
- hipoxemia.', 43)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a29fdb0e-d90a-59f7-946f-6423e8227937', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_44', 'Prioridad', '- sentar/incorporar si tolera;
- oxígeno;
- soporte ventilatorio si necesario;
- monitor;
- acceso IV;
- tratamiento de causa.

---', 44)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('691362f5-fb89-53b3-bca7-50bb807b01f1', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_45', '26. Tratamiento del edema pulmonar', 'Puede incluir:
- oxígeno;
- CPAP/BPAP;
- diuréticos IV;
- nitratos;
- tratamiento de arritmia/isquemia/HTA;
- soporte hemodinámico.

La elección depende de presión arterial, perfusión y causa.', 45)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('27bdec40-3118-5e29-9ed4-bd6ab18863b5', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_46', 'Error', 'Administrar grandes volúmenes IV rutinariamente a un paciente con congestión evidente.

---', 46)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('743fb834-cb39-5fe6-84b7-d6114b8f1841', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_47', '27. Trombosis venosa profunda (TVP)', 'Factores basados en triada de Virchow:
- estasis;
- lesión endotelial;
- hipercoagulabilidad.

Riesgos:
- cirugía;
- inmovilidad;
- cáncer;
- embarazo;
- trombofilia;
- antecedentes;
- edad;
- otros.

Signos:
- edema unilateral;
- dolor;
- calor;
- aumento de perímetro.

No todos están presentes.

---', 47)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ca7a8bde-1f48-55c8-a731-386af8a9df01', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_48', '28. Embolia pulmonar (EP)', 'Merck, actualizado en enero de 2026, define EP como oclusión de arterias pulmonares por trombos, habitualmente originados en venas profundas de piernas/pelvis.

Manifestaciones:
- disnea súbita;
- dolor pleurítico;
- taquipnea;
- taquicardia;
- hipoxemia;
- síncope;
- hipotensión/shock en casos graves.', 48)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('452847fe-3401-57ff-b6b8-3216ac4a1995', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_49', 'Prioridad', 'EP de alto riesgo puede causar paro.

---', 49)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8123f521-c95c-560f-a563-1fa9d7acce3e', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_50', '29. Conducta ante sospecha de TVP/EP', '', 50)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4b182e6a-47c2-5a0e-a9d5-aec71c1d8110', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_51', 'TVP', '- valorar;
- evitar masajear la extremidad;
- limitar maniobras innecesarias;
- notificar;
- realizar estudios/tratamiento prescrito.', 51)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8680d5aa-9b0e-54e0-904d-0f96007446b9', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_52', 'EP', '- ABC;
- oxígeno si requiere;
- monitor;
- acceso;
- respuesta urgente;
- anticoagulación/trombólisis/intervención según riesgo y orden.

---', 52)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('170f37b0-4bc0-5a39-82ec-a02096801089', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_53', '30. Anticoagulación: seguridad', 'Vigilar:
- sangrado;
- hemoglobina;
- plaquetas;
- función renal;
- interacciones;
- signos neurológicos;
- heces/orina.

Educar:
- adherencia;
- signos de sangrado;
- evitar medicamentos no prescritos que aumenten riesgo;
- seguimiento.

---', 53)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('532c7c29-e168-55c1-a719-7413ed704ca7', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_54', '31. Aneurisma aórtico', 'Un aneurisma es dilatación anormal de una arteria.

Puede ser:
- abdominal;
- torácico.

Muchos son asintomáticos hasta complicarse.

Factores:
- edad;
- tabaquismo;
- hipertensión;
- aterosclerosis;
- antecedentes familiares;
- trastornos del tejido conectivo.

---', 54)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('0b675bfb-82da-5198-858f-e92622be351b', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_55', '32. Aneurisma abdominal', 'Puede manifestarse con:
- masa pulsátil;
- dolor abdominal;
- dolor lumbar.', 55)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('18a67d07-3e35-57d3-a6d9-40c1a3dab4d4', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_56', 'Ruptura', 'Puede producir:
- dolor súbito intenso;
- hipotensión;
- shock;
- síncope.

Es una emergencia quirúrgica.', 56)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6e3010b9-3404-5c44-816f-1c0a0539e81f', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_57', 'Seguridad', 'No palpar repetidamente/agresivamente una masa pulsátil sospechosa.

---', 57)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2fcd95b1-04a5-5e69-b6ee-e2cbc64f08fd', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_58', '33. Aneurisma torácico y disección', 'Aneurisma torácico puede producir:
- dolor torácico/espalda;
- disfagia;
- ronquera;
- tos;
- síntomas por compresión.

Disección:
- dolor súbito intenso, frecuentemente torácico o dorsal;
- déficit de pulsos;
- diferencia de presión;
- síncope;
- déficit neurológico;
- shock.', 58)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2a8a7d17-c4b8-5457-82ed-6368299d9ec3', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_59', 'Prioridad', 'Sospecha de disección/ruptura requiere respuesta inmediata y control hemodinámico especializado.

---', 59)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8afdc9d0-9ef9-5c64-9717-0f6b12afcc3e', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_60', '34. Hipertensión arterial', 'La guía AHA/ACC 2025 mantiene categorías:

- normal: <120/<80 mmHg;
- elevada: 120–129 y <80;
- estadio 1: 130–139 o 80–89;
- estadio 2: ≥140 o ≥90.', 60)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5976b680-2415-5668-bdee-ed11ccc475c7', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_61', 'Diagnóstico', 'No debe basarse en una medición aislada en la mayoría de situaciones no urgentes.

---', 61)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8936b639-c983-5c01-97b5-3b0d1c5b5ae9', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_62', '35. Técnica correcta de presión arterial', 'Para reducir errores:
- paciente en reposo;
- brazo apoyado;
- manguito adecuado;
- espalda apoyada;
- pies en el suelo;
- sin hablar;
- brazo a nivel del corazón;
- repetir mediciones cuando corresponda.

Un manguito demasiado pequeño puede sobreestimar la presión.

---', 62)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('dd99f853-0ae3-5435-ae73-c647e3686acd', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_63', '36. Hipertensión severa vs emergencia hipertensiva', 'AHA 2025 considera **hipertensión severa** en no embarazadas cuando PA es >180/120 mmHg **sin evidencia de daño agudo de órgano diana**.

En general se evalúa y trata de forma ambulatoria con ajuste oportuno de terapia oral.', 63)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b63f55ae-9860-5f34-a42d-f814111f5128', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_64', 'Emergencia hipertensiva', 'PA muy elevada **con daño agudo de órgano diana**.

Ejemplos:
- encefalopatía;
- ACV;
- SCA;
- edema pulmonar;
- disección aórtica;
- lesión renal aguda.

Requiere tratamiento hospitalario urgente.', 64)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('27fda7dd-ce53-5277-bd99-e91877eacea6', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_65', 'Clave CICDE', '**El número solo no define emergencia; importa el daño agudo de órgano.**

---', 65)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b38b8bb8-658f-5dd3-973d-ef65c50a665c', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_66', '37. Síntomas de alarma con PA >180/120', '- dolor torácico;
- disnea;
- dolor de espalda;
- déficit neurológico;
- cambios visuales;
- dificultad para hablar;
- alteración de conciencia.', 66)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a7f7975c-b843-5631-82c5-510d8376a454', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_67', 'Conducta', 'Evaluar como posible emergencia hipertensiva.

---', 67)
