INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b737bb1e-9dd4-557c-81df-489bd1380d17', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_78', 'Caso 2 — Oxígeno', 'Paciente con SCA tiene SpO₂ 98% sin disnea.

**Concepto:** oxígeno no es automático si no hay hipoxemia/indicación.', 78)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c15a715f-18f0-5a93-8913-54b8797d16c8', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_79', 'Caso 3 — Taquicardia inestable', 'Paciente con taquicardia presenta hipotensión y alteración mental.

**Conducta:** arritmia inestable; preparar cardioversión sincronizada según algoritmo.', 79)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('891a5641-4409-517d-b6e8-9bbe3279a007', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_80', 'Caso 4 — FV', 'Paciente sin pulso en fibrilación ventricular.

**Prioridad:** RCP + desfibrilación rápida.', 80)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
