VALUES ('60095c13-4730-5f83-bf7b-8e0e8fab9d5b', 'c2fbc835-1110-52d9-ac9f-3b1624b17f99', 'sec_100', 'Aneurisma', '**Merck Manual Professional Edition. Thoracic Aortic Aneurysms.**

