INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f209c15f-dc94-59c7-975e-e2ea1466b922', 'e9317d94-aec9-51fa-8ecb-1f6e438622c4', 'sec_7', 'Plaquetas', 'Contribuyen a la hemostasia primaria mediante adhesión, activación y agregación.', 7)
