INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4aa035bd-7430-5117-b6cd-092e3daa38ba', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_49', 'Evaluación', '- función;
- dolor;
- movilidad;
- estado neurovascular;
- independencia.

---', 49)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('41c0435f-8a41-5364-9ac4-dd3d64e21ef2', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_50', '30. Situaciones tipo examen', '', 50)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2b5b01f6-280f-53ec-aa2e-54046f15a1d6', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_51', 'Caso 1', 'Trabajador realiza levantamientos repetidos con giro de tronco.

**Riesgo:** combinación de fuerza + repetición + postura forzada.', 51)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('95596318-f0cb-5bf3-bf55-9ab7645c0cc9', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_52', 'Caso 2', 'Paciente con yeso presenta dolor creciente y parestesias.

**Prioridad:** valorar compromiso neurovascular/síndrome compartimental.', 52)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a5d666a6-97bd-5ba3-9bfc-0dbd4e4ad8cd', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_53', 'Caso 3', 'Paciente tiene pulso distal, pero dolor extremo con estiramiento pasivo.

**Concepto:** pulso presente no descarta síndrome compartimental.', 53)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('aade20e2-ff8e-51c4-8698-913c304b9048', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_54', 'Caso 4', 'Persona con dolor lumbar presenta retención urinaria y anestesia en silla de montar.

**Prioridad:** emergencia neurológica compatible con cauda equina.', 54)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('869f5e84-0e3b-5b00-a799-fc3f5b4bba6b', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_55', 'Caso 5', 'Paciente con dolor lumbar crónico permanece en cama desde hace semanas.

**Conducta:** favorecer recuperación funcional y actividad progresiva, no reposo prolongado rutinario.', 55)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7b43763b-b60a-5426-b497-a5eda86617cd', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_56', 'Caso 6', 'Paciente con articulación caliente, edematosa y fiebre.

**Prioridad:** descartar infección articular.', 56)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('bbe4e1bd-0a41-5bdc-8898-71a96512aaa8', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_57', 'Caso 7', 'Fractura abierta.

**Conducta:** cubrir, controlar hemorragia, inmovilizar, valorar neurovascular; no reintroducir hueso.', 57)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('21a9690d-c195-5d93-ad36-4644bbd706e7', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_58', 'Caso 8', 'Paciente introduce una regla dentro del yeso para rascarse.

**Educación:** no introducir objetos por riesgo de lesión/infección.', 58)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ead7e929-c7bc-5db2-b04f-19f494559fae', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_59', 'Caso 9', 'Paciente mayor con debilidad, sedación y mala visión ha caído dos veces.

**Conducta:** prevención multifactorial, no una sola intervención.', 59)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6133f1f4-c386-5a84-b3df-d2ffb3b853f5', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_60', 'Caso 10', 'Trabajo con vibración y postura estática prolongada.

**Interpretación:** ambos son factores de riesgo musculoesquelético reconocidos.', 60)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9d80e1b6-b13a-5f0b-8536-e40422cfe1b3', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_61', 'Caso 11', 'Paciente con artrosis deja toda actividad física.

**Conducta:** explicar que actividad/fortalecimiento adaptados suelen formar parte del manejo.', 61)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a4d5b5cd-a95e-5a75-a3cd-780f357c16a5', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_62', 'Caso 12', 'Paciente con yeso presenta dedos fríos y adormecidos.

**Prioridad:** evaluación neurovascular inmediata.

---', 62)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c590e016-768f-596e-89a5-0bd26619a65f', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_63', '31. Errores frecuentes', '1. Valorar solo dolor y no función.
2. No revisar estado neurovascular.
3. Creer que un pulso presente descarta síndrome compartimental.
4. Esperar parálisis o ausencia de pulso para actuar.
5. Recomendar reposo prolongado a todo dolor lumbar.
6. Omitir factores ocupacionales.
7. Levantar pacientes sin ayudas disponibles.
8. Considerar toda lumbalgia “muscular” sin buscar alarmas.
9. Introducir objetos bajo yeso.
10. Reintroducir hueso de fractura abierta.
11. Ignorar articulación caliente con fiebre.
12. No planear rehabilitación.

---', 63)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('17b5f2f5-1e43-5be6-95c2-e2fc65889aa1', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_64', '32. Qué memorizar', '**NIOSH: fuerza + repetición + postura forzada + vibración = riesgos importantes.**

**Función importa tanto como dolor.**

**Extremidad lesionada: valorar neurovascular antes y después de inmovilizar.**

**Síndrome compartimental: dolor desproporcionado + dolor con estiramiento pasivo.**

**Pulso presente NO lo descarta.**

**Cauda equina = síntomas esfinterianos/silla de montar + déficit → emergencia.**

**Rehabilitación y actividad segura son centrales.**

---', 64)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('07aff59f-f8fc-5798-83f0-111876709fd3', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_65', '33. Fuentes', '', 65)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('fc3ed708-bf26-5c41-b55e-181b3b7c8c6d', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_66', 'Fuente rectora', '**CICDE Panamá. Lineamientos para el Examen de Competencias de Profesionales de Enfermería, 2026.**', 66)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('dd987f70-611d-5031-a350-58e59592969c', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_67', 'Fuentes CICDE', '**Hinkle, J. L.; Cheever, K. H. Brunner y Suddarth. Enfermería Médicoquirúrgica. 14.ª edición, 2019.**

**Potter, P. A. et al. Fundamentos de Enfermería. 11.ª edición, 2023.**', 67)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('19fc5b95-35d8-5724-a9b5-40e4f24ed093', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_68', 'Fuentes complementarias', '**OMS. Musculoskeletal health.**

**OMS. Guideline for non-surgical management of chronic primary low back pain in adults, 2023.**

**CDC/NIOSH. Ergonomics — Identify Risk Factors.**

**Merck Manual Professional Edition. Evaluation of the Patient With Joint Symptoms, actualizado 2025.**

**Merck Manual Professional Edition. Compartment Syndrome, revisión 2025.**

---', 68)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('67d04b5c-21b0-5ecc-83b6-d79a1afcbfde', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_69', '34. Control de calidad', 'Este paquete:
- conserva el foco exacto CICDE en factores de riesgo musculoesqueléticos;
- utiliza OMS y NIOSH;
- incluye valoración y función;
- incorpora prevención ocupacional;
- incluye red flags de lumbalgia;
- incorpora fracturas únicamente como contexto clínico relevante;
- enfatiza síndrome compartimental;
- contiene 12 casos originales.

---', 69)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e1e08dfc-3db4-5262-82cb-0f7433a8d22e', '2738b49f-f7db-5d6f-a7b7-2d16242dd30d', 'sec_70', '35. Estado para integración', '**Estado recomendado:** `REVIEW`

Antes de `VERIFIED`:
- registrar `reviewed_by` y `reviewed_at`;
- vincular fuentes;
- enlazar con ADULT-06 discapacidad, ADULT-07 adulto mayor, ADULT-08 dolor y ADULT-29 emergencias.', 70)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('925d8935-9397-5831-b19e-3e174aa455e9', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_1', 'Trastornos gastrointestinales y del recto', '**Área:** Salud del Adulto  
**Código:** ADULT-21  
**Estado académico del paquete:** `REVIEW`  
**Última revisión del paquete:** 2026-09-10

---', 1)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('48720da9-ca67-50a9-86ca-a0c7f4311983', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_2', '1. Alcance oficial CICDE', 'El lineamiento CICDE 2026 especifica:', 2)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('3b71e88d-828a-5908-8cc9-16186572f210', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_3', 'Trastornos gastrointestinales y del recto', '- estreñimiento;
- diarrea;
- incontinencia;
- apendicitis;
- obstrucción intestinal;
- alimentación parenteral;
- tratamientos digestivos y gastrointestinales.

Este módulo desarrolla **todos los elementos expresamente listados**.

---', 3)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2edc3e3c-b9b9-5323-993a-9de6e373fd39', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_4', '2. Objetivos', 'El estudiante debe poder:

1. Realizar valoración gastrointestinal básica.
2. Diferenciar estreñimiento, impactación e incontinencia fecal.
3. Identificar causas y signos de alarma de diarrea.
4. Prevenir deshidratación y alteraciones electrolíticas.
5. Reconocer apendicitis y complicaciones.
6. Reconocer obstrucción intestinal y estrangulación.
7. Aplicar seguridad con laxantes y antidiarreicos.
8. Comprender indicaciones generales de sonda nasogástrica y descompresión.
9. Explicar cuándo se considera nutrición parenteral.
10. Diferenciar nutrición enteral y parenteral.
11. Vigilar complicaciones metabólicas e infecciosas de nutrición parenteral.
12. Reconocer síndrome de realimentación.
13. Integrar el PAE y resolver casos clínicos.

---', 4)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e07ea9c2-0de4-5209-afb7-609a11b3bdb6', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_5', '3. Valoración gastrointestinal', '', 5)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e03a13c6-4de5-54b9-8bf7-9d8d23a98cc4', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_6', 'Historia', '- dolor;
- náuseas/vómitos;
- apetito;
- peso;
- disfagia;
- reflujo;
- distensión;
- patrón intestinal habitual;
- frecuencia;
- consistencia;
- sangre/moco;
- medicamentos;
- dieta;
- viajes;
- antibióticos;
- cirugía abdominal;
- enfermedad previa.', 6)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('3671a295-47e8-5b30-9d09-e203b9922728', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_7', 'Examen', '- inspección;
- auscultación;
- percusión;
- palpación según situación;
- signos de deshidratación;
- estado general.

---', 7)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6aa2e505-cd6b-5544-9c9f-7f9469540977', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_8', '4. Dolor abdominal: signos de alarma', '- dolor súbito intenso;
- rigidez;
- defensa/peritonismo;
- hematemesis;
- melena o sangrado significativo;
- hipotensión;
- síncope;
- distensión progresiva;
- vómitos persistentes;
- ausencia de gases/heces;
- fiebre con deterioro;
- alteración de conciencia.', 8)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9f9912b3-e93f-55fe-bd6d-25400bc7b492', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_9', 'Principio', 'Un abdomen agudo requiere evaluación, no tratamiento sintomático aislado.

---', 9)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('75b74492-f851-50d7-a8d2-075771da30bf', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_10', '5. Estreñimiento', 'Merck 2026 lo define como:

- evacuación difícil o infrecuente;
- heces duras;
- sensación de evacuación incompleta.

La frecuencia intestinal normal varía entre personas.', 10)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4cd4eba9-7be6-527b-a00f-35547521277f', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_11', 'Clave', '**No evacuar todos los días no significa necesariamente estreñimiento.**

---', 11)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('496c6a38-0c0d-59f9-8a4b-4aff8d6ebc46', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_12', '6. Factores de riesgo de estreñimiento', '- baja ingesta de fibra;
- poca actividad;
- líquidos insuficientes;
- opioides;
- anticolinérgicos;
- hierro;
- calcio;
- trastornos neurológicos;
- hipotiroidismo;
- diabetes;
- cambios de rutina;
- inmovilidad;
- trastornos del piso pélvico.

---', 12)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9598cf1e-2716-517a-9140-4d4dd60deca9', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_13', '7. Valoración del estreñimiento', 'Preguntar:

- patrón habitual;
- inicio;
- esfuerzo;
- consistencia;
- sensación de bloqueo;
- evacuación incompleta;
- maniobras manuales;
- sangre;
- pérdida de peso;
- medicamentos;
- laxantes/enemas;
- dolor/distensión.', 13)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('22bb1e5d-382e-54cf-819d-cee32dfbe9c3', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_14', 'Alarma', 'Estreñimiento nuevo y persistente, sangre, pérdida de peso o signos de obstrucción requieren estudio.

---', 14)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('eca70709-7748-50e9-a4fd-04ac0afb1530', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_15', '8. Impactación fecal', 'Puede causar:

- dolor;
- distensión;
- pérdida de apetito;
- incontinencia por rebosamiento;
- salida de líquido alrededor del fecaloma.', 15)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('646c318a-4629-5a5b-8023-9491e7b7aa4a', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_16', 'Clave CICDE', 'La “diarrea” líquida en un paciente estreñido puede ser **diarrea por rebosamiento**, no una gastroenteritis.

---', 16)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('14415671-0f34-575a-a155-c77a5a399d76', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_17', '9. Tratamiento del estreñimiento', 'Depende de causa.

Puede incluir:
- actividad;
- líquidos si no están restringidos;
- fibra en pacientes apropiados;
- entrenamiento intestinal;
- tratamiento de causa;
- laxantes.

La guía AGA/ACG 2023 evalúa tratamientos farmacológicos para estreñimiento idiopático crónico.', 17)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6b5d20c3-75d6-5f3d-8231-68aa0eb2b8b0', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_18', 'Seguridad', 'Fibra y laxantes **no deben utilizarse indiscriminadamente** cuando existe:
- sospecha de obstrucción;
- abdomen agudo;
- dolor de origen no aclarado.

---', 18)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2baf5aa1-4ce6-5ba8-8c5a-c8c57d781cdc', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_19', '10. Laxantes — grupos generales', '- formadores de masa;
- osmóticos;
- estimulantes;
- ablandadores;
- secretagogos/procinéticos específicos.

La selección depende de:
- causa;
- edad;
- función renal;
- medicamentos;
- duración;
- riesgo de impactación.

Evitar abuso.

---', 19)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('44d371ba-1084-57fa-b6ad-db2e466ae51b', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_20', '11. Diarrea', 'Merck 2026 la describe como aumento anormal de liquidez/volumen de heces; clínicamente se valora también el incremento del patrón respecto a lo habitual.

Puede ser:

- aguda;
- persistente;
- crónica.

---', 20)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8d5ce3f5-902d-5fa7-b934-9319b83f9f11', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_21', '12. Mecanismos generales de diarrea', '- osmótica;
- secretora;
- inflamatoria;
- malabsorción;
- alteración de motilidad.

Etiologías:
- infecciones;
- medicamentos;
- antibióticos;
- enfermedad inflamatoria;
- malabsorción;
- endocrinopatías;
- otros trastornos.

---', 21)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('983b3791-c28a-5df3-ad57-eb3afc6d57eb', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_22', '13. Valoración de diarrea', '- duración;
- frecuencia;
- volumen;
- sangre/moco;
- fiebre;
- dolor;
- vómitos;
- exposición alimentaria;
- viajes;
- contactos;
- antibióticos;
- hospitalización;
- inmunosupresión;
- diuresis;
- signos de deshidratación.

---', 22)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4d867ec0-9748-5bb5-8ce6-bdff97ebc503', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_23', '14. Complicaciones de diarrea', '- deshidratación;
- hipovolemia;
- alteraciones de sodio;
- hipopotasemia;
- lesión renal;
- acidosis;
- desnutrición;
- lesiones de piel;
- transmisión de infección.', 23)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('619a5cbd-7b89-5e0d-9b61-71fe6a3449e5', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_24', 'Prioridad', 'Primero valorar volumen, perfusión y electrolitos cuando la pérdida es importante.

---', 24)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('41201afb-5394-59a0-92c9-79df0f7f25a9', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_25', '15. Diarrea infecciosa y control de infección', 'Puede transmitirse:
- alimentos;
- agua;
- persona-persona;
- zoonosis.

Aplicar:
- higiene de manos;
- precauciones según agente;
- manejo seguro de excretas;
- limpieza ambiental.

---', 25)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('3ec849e5-e1f5-5070-a3d0-3164fb737eda', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_26', '16. Clostridioides difficile', 'Sospechar especialmente ante:
- diarrea después de antibióticos;
- hospitalización;
- edad avanzada;
- exposición sanitaria.

Puede causar:
- colitis;
- megacolon tóxico;
- perforación;
- sepsis.', 26)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8cecb172-ddd1-52ed-96d7-73144c930560', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_27', 'Enfermería', '- aislar según protocolo;
- higiene de manos;
- controlar heces;
- hidratación;
- administrar tratamiento prescrito;
- vigilar distensión/deterioro.

---', 27)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c6f5c2ca-3022-5199-b835-3d92c08d74ce', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_28', '17. Antidiarreicos', 'Los fármacos antimotilidad pueden ser útiles en algunos adultos con diarrea acuosa no complicada.', 28)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7a55238a-83ed-5c93-a847-1bb525bd23b8', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_29', 'Evitar/cautela', 'No deben utilizarse de forma rutinaria cuando existe:
- sangre;
- fiebre importante;
- sospecha de colitis invasiva;
- C. difficile;
- megacolon;
- otras contraindicaciones.', 29)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('862ebdb7-96fb-511d-9879-82b591dd9f87', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_30', 'Clave', 'Controlar síntomas sin empeorar una infección o retener toxinas.

---', 30)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('68710efb-b941-59c8-8795-5fcdd54bdfbd', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_31', '18. Rehidratación', 'Cuando es posible:
- vía oral es preferible para deshidratación leve/moderada.

En pérdida grave, shock o intolerancia:
- líquidos IV según condición.

Valorar:
- sodio;
- potasio;
- creatinina;
- diuresis;
- peso;
- signos vitales.

---', 31)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f9193258-0437-5bf8-837e-8d74381c54ad', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_32', '19. Incontinencia fecal', 'Merck 2025 la define como evacuación involuntaria de heces.

Causas posibles:
- lesión esfinteriana;
- enfermedad neurológica;
- diabetes;
- demencia;
- prolapso;
- fecaloma;
- inflamación;
- tumor;
- lesión obstétrica.

---', 32)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f03eee9b-08b7-5c71-926b-4281be33ce6b', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_33', '20. Valoración de incontinencia fecal', '- inicio;
- tipo de heces;
- urgencia;
- conciencia;
- movilidad;
- medicamentos;
- estreñimiento/impactación;
- diarrea;
- antecedentes obstétricos;
- cirugía;
- función neurológica;
- integridad de piel.', 33)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('52d0c0aa-a3cd-5129-b5eb-9a02d002971d', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_34', 'Importante', 'No asumir que es inevitable por edad.

---', 34)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5ded5a3a-4536-5e8e-a435-929e08b2d6cd', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_35', '21. Manejo de incontinencia', 'Puede incluir:
- tratar diarrea/estreñimiento;
- programa intestinal;
- ajuste de dieta;
- entrenamiento;
- ejercicios de piso pélvico;
- biofeedback;
- cuidado de piel;
- dispositivos/procedimientos especializados.

Objetivos:
- dignidad;
- continencia cuando sea posible;
- prevenir dermatitis;
- mejorar función.

---', 35)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('3a1ac848-5573-5c3e-92bd-bd1cbbb3443c', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_36', '22. Apendicitis', 'Es inflamación aguda del apéndice.

Frecuentemente ocurre por obstrucción luminal que progresa a:
- distensión;
- proliferación bacteriana;
- isquemia;
- inflamación;
- necrosis/perforación si avanza.

---', 36)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('66b76662-6f42-5fb1-9f0a-6fe7c059e3fc', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_37', '23. Manifestaciones de apendicitis', 'Patrón clásico:
- dolor periumbilical/epigástrico;
- luego migración a cuadrante inferior derecho;
- anorexia;
- náuseas/vómitos;
- febrícula;
- sensibilidad localizada.', 37)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('783c5db1-3331-59ed-b6d2-48a11ce84a0d', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_38', 'Importante', 'Presentaciones atípicas son comunes, especialmente:
- personas mayores;
- embarazo;
- inmunosupresión.

Un leucograma normal no excluye por sí solo el diagnóstico.

---', 38)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('727ab1fe-a634-5250-8f8f-fb988dacbccf', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_39', '24. Diagnóstico de apendicitis', 'Integra:
- historia;
- examen;
- laboratorio;
- ultrasonido/TC según caso.

La edición 2025 de las guías WSES Jerusalem, publicada en JAMA Surgery en 2026, actualiza el enfoque diagnóstico y terapéutico para adultos y grupos especiales.

---', 39)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('80447d79-c688-5b74-9027-557151ef195e', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_40', '25. Tratamiento de apendicitis', 'La apendicectomía sigue siendo tratamiento estándar en muchos pacientes.

Las guías modernas reconocen que en **casos seleccionados de apendicitis no complicada**, un manejo no operatorio con antibióticos puede ser una alternativa según:
- imagen;
- presencia de apendicolito;
- riesgo de recurrencia;
- preferencias;
- evaluación quirúrgica.', 40)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('071d4c80-4b17-57a7-8212-218710243ef0', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_41', 'Enfermería', '- NPO según plan;
- acceso IV;
- líquidos;
- antibióticos;
- analgesia;
- preparación quirúrgica cuando corresponde;
- vigilar perforación/peritonitis.', 41)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('088057a6-760c-5168-8188-24ddf85b492d', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_42', 'Seguridad', 'No retrasar valoración quirúrgica por administrar repetidamente tratamientos sintomáticos.

---', 42)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('0780709a-d4e0-5617-8686-841d7614806e', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_43', '26. Perforación y peritonitis', 'Sospechar si:
- dolor empeora/cambia;
- defensa;
- rigidez;
- fiebre;
- taquicardia;
- deterioro hemodinámico;
- sepsis.

Es una emergencia.

---', 43)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9af5106d-f1bd-5c3c-aec4-2663ecd182d9', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_44', '27. Obstrucción intestinal', 'Merck define obstrucción intestinal como alteración mecánica significativa o detención del tránsito intestinal.

Puede ser:
- parcial;
- completa;
- intestino delgado;
- colon.

Causas comunes:
- adherencias;
- hernias;
- tumores;
- vólvulo;
- impactación;
- otras.

---', 44)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('41cc0791-2092-5ad8-b023-3f808a3a19c2', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_45', '28. Manifestaciones de obstrucción', '- dolor cólico;
- vómitos;
- distensión;
- obstipación;
- ausencia de gases.

En obstrucción parcial puede haber algo de diarrea.', 45)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2f1bf7e4-70db-5a62-b6f2-0b3b0376369c', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_46', 'Importante', 'No descartar obstrucción porque el paciente haya evacuado algo.

---', 46)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('fea7ef9d-8b2c-560b-a3fe-b2626b5a1f26', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_47', '29. Estrangulación/isquemia intestinal', 'Signos preocupantes:
- dolor intenso y continuo;
- sensibilidad;
- peritonismo;
- fiebre;
- taquicardia;
- leucocitosis;
- acidosis;
- shock;
- oliguria.', 47)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4e9b7ccb-37b7-55d7-85e2-83296dcf84ab', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_48', 'Prioridad', 'Puede progresar a necrosis y perforación.

---', 48)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9698bb09-1aaa-5d30-9909-fc817f622fb3', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_49', '30. Manejo de obstrucción', 'Puede incluir:
- hospitalización;
- NPO;
- líquidos IV;
- corrección electrolítica;
- descompresión nasogástrica;
- control de diuresis;
- valoración quirúrgica;
- antibióticos si se sospecha isquemia/perforación;
- cirugía en muchas obstrucciones completas o complicadas.', 49)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('65d1ed5c-8dad-596d-8f8b-664ac520c205', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_50', 'Seguridad', '**No dar laxantes/enemas en sospecha de obstrucción.**

---', 50)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('84e438cf-76e3-5451-a100-966da7dd44b0', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_51', '31. Sonda nasogástrica para descompresión', 'Objetivos:
- retirar contenido/aire;
- disminuir distensión;
- reducir vómitos;
- disminuir riesgo de aspiración en situaciones indicadas.

Cuidados:
- verificar colocación según método institucional;
- mantener permeabilidad;
- registrar débito;
- higiene oral/nasal;
- valorar electrolitos;
- evitar manipulación innecesaria.

---', 51)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a083fe64-d30a-5842-b5c6-16979e9a02fc', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_52', '32. Tratamientos digestivos: principios', 'Dependiendo del problema:

- antieméticos;
- inhibidores de ácido;
- laxantes;
- antidiarreicos;
- antibióticos;
- analgesia;
- líquidos/electrolitos;
- nutrición;
- cirugía;
- endoscopia;
- terapias específicas.', 52)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f47d1256-c950-5aee-9a02-6f7b6e101a98', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_53', 'Clave', 'No existe un “tratamiento gastrointestinal universal”.

---', 53)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f40d397c-dd03-55a2-9220-cefca396ea4c', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_54', '33. Nutrición enteral vs parenteral', '', 54)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('30210717-9a80-572f-afbd-28868623df73', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_55', 'Enteral', 'Utiliza tracto gastrointestinal.', 55)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('eba1b095-37ff-5ff9-ba96-d2aafdc605ed', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_56', 'Parenteral', 'Nutrientes por vía intravenosa.', 56)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('79531dbd-b68c-596d-aeea-e7089c4964e6', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_57', 'Principio', 'Si el tubo digestivo es funcional y puede utilizarse de forma segura, generalmente se prefiere nutrición enteral.

Merck 2025 señala que la nutrición parenteral no debe utilizarse rutinariamente con un tracto GI intacto debido a más complicaciones y peor preservación de función intestinal.

---', 57)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5943d231-9894-54c7-bbdc-2dad18e608b6', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_58', '34. Indicaciones de nutrición parenteral', 'Puede ser necesaria cuando el tracto GI no es funcional o no puede satisfacer necesidades de forma segura.

Ejemplos:
- obstrucción;
- intestino corto;
- algunas fístulas;
- íleo prolongado;
- malabsorción severa;
- otras situaciones especializadas.

La decisión debe ser interdisciplinaria.

---', 58)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('262b9a68-9047-51d6-8124-dcb712b92f95', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_59', '35. Nutrición parenteral periférica y central', '', 59)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('56822351-0b8c-5d5c-9cbe-5d818b2828d8', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_60', 'Periférica', '- limitada por osmolaridad;
- suele utilizarse para necesidades/periodos seleccionados.', 60)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b8041705-6e93-5dd9-a050-8b23fb0d5a45', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_61', 'Central', '- permite soluciones de mayor osmolaridad;
- requiere acceso venoso central.

Merck señala como referencia que soluciones periféricas deben mantenerse alrededor de **≤900 mOsm/L** para reducir riesgo de tromboflebitis.', 61)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e8bcbbeb-e19e-50e5-a911-d5af7fc04311', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_62', 'Seguridad', 'La formulación y acceso dependen del equipo de nutrición y protocolo.

---', 62)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c25358f2-4a65-5d94-995b-37f34a6f4320', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_63', '36. Componentes de nutrición parenteral', 'Puede incluir:

- aminoácidos;
- dextrosa;
- lípidos;
- electrolitos;
- vitaminas;
- oligoelementos;
- agua.

La composición se individualiza según:
- requerimientos;
- función renal/hepática;
- glucemia;
- pérdidas;
- electrolitos;
- condición clínica.

---', 63)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('af6f9f64-a407-54d1-a29c-3532798b4f1f', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_64', '37. Seguridad de administración de PN', 'ASPEN mantiene recursos específicos de seguridad de PN.

Antes/durante:
- verificar paciente;
- fórmula;
- vía;
- velocidad;
- etiqueta;
- fecha;
- compatibilidad;
- filtro cuando corresponda;
- bomba;
- acceso;
- glucemia;
- electrolitos;
- balance;
- signos de infección.', 64)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6bdc751f-5283-51de-a7a5-877b3d08b9b7', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_65', 'Importante', 'No añadir medicamentos a la bolsa o línea sin comprobar compatibilidad y protocolo.

---', 65)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c1400d4d-dd57-59cc-a3af-c9b0352d1446', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_66', '38. Complicaciones de PN', '', 66)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('28e16335-5eab-5396-a891-7ab62a28db59', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_67', 'Metabólicas', '- hiperglucemia;
- hipoglucemia;
- alteraciones electrolíticas;
- hipertrigliceridemia;
- alteraciones hepáticas;
- sobrecarga/deficiencia de líquidos.', 67)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('59900363-4d1f-561c-bc11-03c1935a413f', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_68', 'Acceso', '- infección;
- trombosis;
- oclusión;
- complicaciones mecánicas.

---', 68)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e6e3ab57-a523-5f65-a196-615df10e6c80', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_69', '39. Síndrome de realimentación', 'Puede ocurrir cuando una persona con desnutrición significativa recibe nutrición rápidamente.

Cambios clásicos:
- hipofosfatemia;
- hipopotasemia;
- hipomagnesemia;
- retención de líquidos;
- déficit de tiamina;
- arritmias;
- insuficiencia cardiaca;
- alteraciones neurológicas.', 69)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('57d87422-d6e1-552e-88d6-a34dcbbc60f8', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_70', 'Prevención', '- identificar riesgo;
- corregir/monitorizar electrolitos;
- aportar tiamina cuando corresponde;
- iniciar/progresar nutrición de forma controlada;
- seguimiento estrecho.

---', 70)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('299241e4-83bd-517b-aafe-612c419b1f43', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_71', '40. Hipoglucemia y PN', 'Una interrupción inesperada o modificación de una infusión rica en dextrosa puede contribuir a cambios de glucosa, especialmente en pacientes con insulina asociada.', 71)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('aa9426e7-f05b-500c-acd6-6a4bb8446253', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_72', 'Enfermería', '- controlar glucemia;
- seguir protocolo ante interrupciones;
- no improvisar cambios de velocidad/composición.

---', 72)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('dfb93d9a-c795-573e-aba7-a7e97f9b0cc0', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_73', '41. PAE gastrointestinal', '', 73)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1c500692-d7d4-5a5d-9c39-84dcd670b54f', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_74', 'Valoración', '- dolor;
- distensión;
- evacuaciones;
- vómitos;
- hidratación;
- peso;
- balance;
- piel;
- laboratorios;
- nutrición.', 74)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2dfa8ce8-bf81-5658-ae48-357ea51b9bf7', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_75', 'Diagnóstico/juicio', '- déficit de volumen;
- alteración de eliminación;
- dolor;
- riesgo de infección;
- nutrición alterada;
- riesgo de aspiración.', 75)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ac15a767-3919-57ae-9bf2-6f3a0d68525f', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_76', 'Planificación', 'Priorizar:
- shock;
- sangrado;
- peritonitis;
- obstrucción;
- deshidratación;
- infección.', 76)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('91db7bff-c9b2-593e-81f9-6edb8fd205bb', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_77', 'Implementación', '- NPO cuando indicado;
- líquidos;
- medicamentos;
- higiene;
- descompresión;
- nutrición;
- educación.', 77)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7075dc04-b6df-5f3d-a164-1cb29ee399f3', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_78', 'Evaluación', '- dolor;
- abdomen;
- eliminación;
- balance;
- electrolitos;
- tolerancia;
- signos de complicación.

---', 78)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('42ac3ea0-1a45-5967-b91c-232c10d36bc7', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_79', '42. Situaciones tipo examen', '', 79)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('04280a57-f9e5-55eb-904d-e7bb7cef6a74', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_80', 'Caso 1 — Estreñimiento con distensión', 'Paciente con estreñimiento agudo, vómitos y abdomen distendido solicita laxante.

**Conducta:** evaluar obstrucción antes de administrar laxante.', 80)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ce8a6e19-6027-51ad-b1a4-eb74b5005898', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_81', 'Caso 2 — “Diarrea” con fecaloma', 'Paciente estreñido elimina pequeñas cantidades líquidas alrededor de impactación.

**Interpretación:** diarrea por rebosamiento.', 81)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5d55c8c4-e882-5b50-9857-f811f3a85d71', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_82', 'Caso 3 — Diarrea y antibióticos', 'Paciente hospitalizado desarrolla diarrea tras antibióticos.

**Sospecha:** C. difficile; aplicar precauciones/protocolo y valorar.', 82)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f56c03d8-35d4-5f27-92de-fab03cb7af6a', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_83', 'Caso 4 — Diarrea sanguinolenta', 'Paciente con fiebre y sangre en heces pide antidiarreico de motilidad.

**Conducta:** no administrarlo rutinariamente sin evaluación de infección invasiva.', 83)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4c7ac3e6-b2d2-5d81-a15a-70471380f1a2', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_84', 'Caso 5 — Apendicitis', 'Dolor inicia periumbilical y migra al cuadrante inferior derecho.

**Sospecha:** apendicitis.', 84)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('92662f6d-d707-5eda-b76f-9f4c0bea710b', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_85', 'Caso 6 — Apendicitis atípica', 'Adulto mayor tiene dolor menos localizado y deterioro general.

**Conducta:** no descartar por presentación atípica.', 85)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6e00dc9f-03bd-540a-977e-0c2832a7ed20', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_86', 'Caso 7 — Obstrucción', 'Dolor cólico, vómitos, distensión y ausencia de gases.

**Prioridad:** posible obstrucción; NPO, IV, evaluación y descompresión según orden.', 86)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f9427d9d-1c95-57cf-beda-76b9a1c23321', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_87', 'Caso 8 — Dolor continuo', 'Paciente con obstrucción pasa de dolor cólico a dolor continuo intenso y taquicardia.

**Prioridad:** posible estrangulación/isquemia.', 87)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6d6728ac-1e9a-57c6-85ac-385b2b153746', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_88', 'Caso 9 — PN con GI funcional', 'Paciente puede usar tracto gastrointestinal pero se propone PN sin otra razón.

**Concepto:** enteral suele preferirse si el GI es funcional y seguro.', 88)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('61efffb2-5bbc-5ec0-824d-3a675566f0f8', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_89', 'Caso 10 — PN y fiebre', 'Paciente con PN central presenta fiebre y eritema en acceso.

**Prioridad:** sospechar infección asociada al catéter.', 89)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('96abb600-11df-5b1e-93a9-096e3e8d16ae', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_90', 'Caso 11 — Realimentación', 'Paciente muy desnutrido inicia soporte y desarrolla fósforo bajo, edema y arritmia.

**Sospecha:** síndrome de realimentación.', 90)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f1d83840-3ce1-59c3-a7f7-aa9e2b745206', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_91', 'Caso 12 — Incontinencia fecal', 'Persona mayor con “incontinencia nueva” tiene estreñimiento y masa fecal.

**Conducta:** valorar impactación como causa potencial antes de etiquetar incontinencia permanente.

---', 91)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7cabb6b3-1c09-574e-a571-4c82be1f7c36', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_92', '43. Errores frecuentes', '1. Definir estreñimiento solo por frecuencia.
2. Dar laxante ante posible obstrucción.
3. Confundir rebosamiento con diarrea primaria.
4. Omitir deshidratación/electrolitos en diarrea.
5. Dar antimotilidad con sangre/fiebre sin evaluación.
6. No sospechar C. difficile tras antibióticos.
7. Esperar cuadro clásico de apendicitis en todos.
8. Descartar obstrucción porque hubo algo de diarrea.
9. Ignorar dolor continuo en obstrucción.
10. Utilizar PN cuando el GI es funcional sin indicación.
11. No vigilar glucosa/electrolitos durante PN.
12. Ignorar realimentación.

---', 92)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('08e76b44-75f4-5412-91a1-270a8d71eed8', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_93', '44. Qué memorizar', '**Estreñimiento = dificultad/dureza/incompletitud, no simplemente “no evacuar diario”.**

**Fecaloma puede producir diarrea por rebosamiento.**

**Diarrea: prioridad = hidratación + electrolitos + causa.**

**Antibióticos previos + diarrea = pensar C. difficile.**

**Apendicitis: dolor puede migrar a CID, pero hay presentaciones atípicas.**

**Obstrucción: cólico + vómito + distensión + obstipación/ausencia de gases.**

**Dolor continuo intenso en obstrucción = pensar estrangulación.**

**Sospecha de obstrucción: NO laxantes/enemas.**

**GI funcional y seguro → preferir enteral sobre PN.**

**PN: vigilar infección + glucosa + electrolitos + realimentación.**

---', 93)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('93118174-6d6a-5ea0-95e8-4a8f44c443d3', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_94', '45. Fuentes', '', 94)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2c2cb006-ad37-5d4b-ba18-18578fafeeae', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_95', 'Fuente rectora', '**CICDE Panamá. Lineamientos para el Examen de Competencias de Profesionales de Enfermería, 2026.**', 95)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('52b59b23-7df7-5479-8c4c-3ead3dbf0dcf', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_96', 'Fuentes CICDE', '**Hinkle, J. L.; Cheever, K. H. Brunner y Suddarth. Enfermería Médicoquirúrgica. 14.ª edición, 2019.**

**Potter, P. A. et al. Fundamentos de Enfermería. 11.ª edición, 2023.**', 96)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('febf42c9-debb-58ae-8cd5-d1c6b39693aa', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_97', 'Estreñimiento', '**AGA/ACG Clinical Practice Guideline: Pharmacological Management of Chronic Idiopathic Constipation, 2023.**

**Merck Manual Professional Edition. Constipation, revisión abril 2026.**', 97)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ecbe0a95-30fd-519e-8630-cb090ab1951e', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_98', 'Diarrea', '**Merck Manual Professional Edition. Diarrhea, revisión abril 2026.**', 98)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c92bca72-da14-5095-9465-9bf2834c6dc2', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_99', 'Incontinencia', '**Merck Manual Professional Edition. Fecal Incontinence, revisión enero 2025.**', 99)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('3d86fc5d-2303-59d5-af70-a0ef6aba8b42', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_100', 'Apendicitis', '**World Society of Emergency Surgery. Diagnosis and Treatment of Acute Appendicitis: 2025 Edition of Jerusalem Guidelines; JAMA Surgery, publicación 2026.**

**Merck Manual Professional Edition. Appendicitis.**', 100)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7d37ab38-e05c-5fd4-9cb4-9e3726d58399', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_101', 'Obstrucción', '**Merck Manual Professional Edition. Intestinal Obstruction, revisión 2024.**', 101)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5c410dd9-d2f7-56e9-9953-203358a41605', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_102', 'Nutrición parenteral', '**ASPEN. Parenteral Nutrition Safety resources, actualizados 2024–2026.**

**Merck Manual Professional Edition. Parenteral Nutrition, 2025.**

---', 102)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b97d5899-d403-50b9-8ba6-7e9dd13a85b4', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_103', '46. Control de calidad', 'Este paquete:
- cubre cada subtema explícito CICDE;
- incorpora fuentes GI revisadas en 2026;
- integra la actualización WSES de apendicitis publicada en 2026;
- cubre seguridad de laxantes/antidiarreicos;
- distingue incontinencia y rebosamiento;
- cubre obstrucción y estrangulación;
- incluye PN, acceso, complicaciones y realimentación;
- contiene 12 casos originales.

---', 103)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b867f27b-c266-50fd-8c10-a671cbd07518', '9c731c75-4b32-511b-a474-bfe38c631a0d', 'sec_104', '47. Estado para integración', '**Estado recomendado:** `REVIEW`

Antes de `VERIFIED`:
- registrar `reviewed_by` y `reviewed_at`;
- vincular fuentes;
- enlazar con ADULT-04 nutrición, ADULT-09 líquidos/electrolitos, ADULT-12 perioperatorio y Farmacología;
- mantener velocidades, composiciones y protocolos de PN como contenido institucionalizado, no reglas universales.', 104)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('27935866-f2ab-54c6-a81b-af8f760e4944', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_1', 'Función metabólica y endocrina', '**Área:** Salud del Adulto  
**Código:** ADULT-22  
**Estado académico del paquete:** `REVIEW`  
**Última revisión del paquete:** 2026-09-10

---', 1)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6c98f810-4f0c-5808-8bbf-d261f05eda24', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_2', '1. Alcance oficial CICDE', 'El lineamiento CICDE 2026 incluye expresamente dentro de **Función metabólica y endocrina**:

1. Obesidad.
2. Hepatitis A y B.
3. Trastornos de la vesícula y pancreatitis.
4. Valoración y tratamiento del paciente con diabetes.

Este módulo desarrolla los cuatro componentes sin sustituir protocolos institucionales, prescripciones médicas ni normas nacionales vigentes.

---', 2)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7a38554a-92bf-5204-9035-ffe5baf26db7', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_3', '2. Objetivos de aprendizaje', 'Al finalizar el tema, el estudiante debe poder:

1. Reconocer la obesidad como enfermedad crónica y multifactorial.
2. Calcular e interpretar el IMC como herramienta de tamizaje, reconociendo sus limitaciones.
3. Diferenciar hepatitis A y hepatitis B por transmisión, evolución y prevención.
4. Reconocer signos de hepatitis aguda y de deterioro hepático.
5. Diferenciar cólico biliar, colecistitis, coledocolitiasis y colangitis de forma clínica general.
6. Reconocer pancreatitis aguda, sus causas frecuentes y signos de gravedad.
7. Aplicar prioridades de enfermería en pancreatitis.
8. Diferenciar diabetes tipo 1 y tipo 2.
9. Conocer criterios diagnósticos actuales de diabetes en adultos no embarazados.
10. Reconocer hipoglucemia, cetoacidosis diabética y estado hiperosmolar.
11. Aplicar seguridad con insulina y monitorización de glucosa.
12. Prevenir complicaciones microvasculares y macrovasculares.
13. Educar en autocuidado, alimentación, actividad, medicamentos y signos de alarma.
14. Integrar el PAE y resolver situaciones tipo examen.

---', 3)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ff59aced-5287-5bcd-95f1-7c760dfc0961', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_4', '3. OBESIDAD', '', 4)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('01977680-6063-5ed2-9da4-a29ad790a663', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_5', 'Concepto actual', 'La OMS, en su actualización de diciembre de 2025, caracteriza la obesidad como una **enfermedad crónica y con posibilidad de recaída**, producto de interacciones complejas entre:

- genética;
- neurobiología;
- conductas alimentarias;
- acceso a alimentación saludable;
- ambiente;
- determinantes sociales;
- fuerzas de mercado;
- actividad física;
- otros factores.', 5)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5f718dcd-b0ac-5c55-9998-8a4df40dd958', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_6', 'Clave de enfermería', 'La obesidad no debe abordarse como un simple problema de “falta de voluntad”.

---', 6)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('276a4f9d-05d8-5224-b8cc-c380986308ef', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_7', '4. IMC', '**IMC = peso (kg) ÷ talla² (m²)**

En adultos, OMS utiliza como referencia general:

- sobrepeso: IMC ≥25 kg/m²;
- obesidad: IMC ≥30 kg/m².', 7)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e3da14ee-1948-59b1-aea4-c096c0567123', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_8', 'Limitaciones', 'El IMC:
- no distingue grasa de masa muscular;
- no describe distribución adiposa;
- no sustituye una valoración clínica;
- debe interpretarse junto con antecedentes, función, comorbilidades y otras medidas.

La circunferencia de cintura puede aportar información adicional sobre adiposidad central.

---', 8)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2171c956-9383-5a55-b794-b197d1fda2f8', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_9', '5. Consecuencias asociadas con obesidad', 'Se relaciona con mayor riesgo de:

- diabetes tipo 2;
- hipertensión;
- enfermedad cardiovascular;
- apnea obstructiva del sueño;
- enfermedad renal;
- enfermedad hepática metabólica;
- osteoartrosis;
- algunos cánceres;
- limitación funcional.

La asociación no implica que todas las personas desarrollarán estas complicaciones.

---', 9)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('fc593ad6-1cf4-5d51-abd3-af763e37e43b', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_10', '6. Valoración de la persona con obesidad', 'Evaluar:

- historia de peso;
- medicamentos;
- patrón alimentario;
- actividad;
- sueño;
- salud mental;
- entorno;
- limitaciones funcionales;
- presión arterial;
- glucosa;
- lípidos;
- riesgo cardiovascular;
- signos de apnea del sueño;
- enfermedad hepática/metabólica;
- objetivos y preferencias.', 10)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5e309a01-a043-5473-a70d-b8ee8d29218f', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_11', 'Comunicación', 'Utilizar lenguaje respetuoso, pedir permiso antes de hablar del peso y evitar estigma.

---', 11)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('03c679cf-a3bb-5369-89cb-e186861cfa41', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_12', '7. Tratamiento de obesidad', 'Puede combinar:

- intervención nutricional;
- actividad física;
- cambios conductuales;
- apoyo psicológico;
- tratamiento farmacológico;
- cirugía metabólica/bariátrica en personas seleccionadas;
- manejo de comorbilidades.', 12)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e7247c4f-5c57-5f37-bb16-5d453835ebd2', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_13', 'Principio', 'El objetivo no es únicamente “bajar kilos”; también importa:
- función;
- salud cardiometabólica;
- calidad de vida;
- sostenibilidad;
- reducción de riesgos.

---', 13)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('63bae116-9e8f-52a5-b0e2-31e2cd420519', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_14', '8. HEPATITIS A', '', 14)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('daf5eeef-03f3-5ec5-8229-ba6a24b66571', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_15', 'Concepto', 'La hepatitis A es una infección hepática causada por HAV.

CDC 2025 confirma:

- transmisión principalmente fecal-oral;
- prevención principal mediante vacunación;
- la infección por hepatitis A es **aguda**;
- **no se vuelve crónica**.

---', 15)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('95831cd4-54b0-5aff-8693-b98ea3dde579', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_16', '9. Transmisión de hepatitis A', 'Puede ocurrir por:

- alimentos o agua contaminados;
- contacto cercano persona-persona;
- determinadas prácticas sexuales;
- higiene deficiente en contextos de transmisión.', 16)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b24b163f-b759-592c-85ab-b644d9e60f19', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_17', 'Prevención', '- vacunación según esquema;
- higiene de manos;
- agua segura;
- manipulación segura de alimentos;
- medidas posteriores a exposición según indicación.

---', 17)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('868270de-9d3a-5b72-bbeb-a87df98dc885', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_18', '10. Manifestaciones de hepatitis A', 'Pueden incluir:

- fatiga;
- anorexia;
- náuseas;
- vómitos;
- dolor abdominal;
- fiebre;
- orina oscura;
- heces claras;
- ictericia.

Algunas personas pueden presentar infección asintomática.

---', 18)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f1721f87-3e5f-5f2b-9c88-5d99bfb6fa2d', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_19', '11. Tratamiento de hepatitis A', 'Generalmente es de soporte:

- hidratación;
- alimentación según tolerancia;
- reposo relativo;
- control de síntomas;
- evitar hepatotóxicos innecesarios;
- vigilancia de deterioro.', 19)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2529205d-1391-5332-88ca-7e226ebdb1db', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_20', 'Alarma', 'Alteración de conciencia, coagulopatía, hipoglucemia o deterioro rápido pueden sugerir insuficiencia hepática aguda y requieren atención urgente.

---', 20)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c4a65703-4a13-58d0-b37d-a774d075528c', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_21', '12. HEPATITIS B', '', 21)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f858bae1-68c0-551e-a93a-c35324c9aa0a', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_22', 'Concepto', 'La hepatitis B es infección causada por HBV.

A diferencia de HAV:

- puede ser aguda;
- puede hacerse crónica;
- puede producir cirrosis;
- aumenta riesgo de carcinoma hepatocelular.

---', 22)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('502abb68-22ea-569f-9046-f8c6b04bd0be', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_23', '13. Transmisión de hepatitis B', 'CDC describe transmisión cuando sangre, semen u otros fluidos corporales infectados ingresan al organismo.

Vías importantes:

- perinatal;
- sexual;
- agujas/equipos contaminados;
- exposiciones percutáneas;
- exposición ocupacional;
- compartir material contaminado con sangre.', 23)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('22ba8d49-5bfb-5362-8892-9aca7a459a63', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_24', 'No se transmite por contacto social casual.', '---', 24)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8d6764e2-7aaf-546d-b248-d538598303ab', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_25', '14. Prevención de hepatitis B', '- vacunación;
- precauciones estándar;
- prácticas sexuales seguras;
- seguridad de agujas/cortopunzantes;
- no compartir equipos contaminados;
- tamizaje apropiado;
- profilaxis postexposición cuando corresponda.', 25)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a18d7c78-dc75-5288-b482-38811024c19f', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_26', 'Seguridad en glucómetros', 'Nunca compartir dispositivos de punción digital entre personas. Los glucómetros reutilizables deben limpiarse/desinfectarse conforme a instrucciones y política institucional.

---', 26)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2d01c400-61c5-5c14-a5f7-82e66f0ea736', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_27', '15. Tamizaje de hepatitis B', 'CDC recomienda para el tamizaje inicial en adultos el **panel triple**:

- HBsAg;
- anti-HBs;
- anti-HBc total.

La interpretación debe considerar el patrón completo.', 27)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('3e6204c7-a995-5269-996c-e35d1909b435', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_28', 'Embarazo', 'HBsAg debe evaluarse en cada embarazo conforme a los programas aplicables.

---', 28)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a1c9d6e2-4fde-502b-904e-f66f45612773', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_29', '16. Hepatitis B aguda y crónica', '', 29)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('26bb8e7e-5a53-5a69-aca9-dc650ce47bcd', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_30', 'Aguda', 'Puede ser asintomática o producir:
- fatiga;
- anorexia;
- náuseas;
- dolor abdominal;
- ictericia;
- orina oscura.

El tratamiento suele ser de soporte.', 30)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d6a27f17-47b7-5a46-8fd6-68310fe082d7', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_31', 'Crónica', 'Puede permanecer asintomática por años.

Requiere:
- seguimiento;
- valoración de actividad hepática;
- evaluación de fibrosis;
- vigilancia de cáncer en personas elegibles;
- tratamiento antiviral en quienes cumplen criterios.', 31)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6fa67a98-2794-563a-9c8e-fd86f5cac728', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_32', 'Clave', 'No todas las personas con HBV crónico requieren exactamente el mismo tratamiento farmacológico.

---', 32)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c115bbc7-acbb-5e27-b0c3-8770338b8993', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_33', '17. Signos de deterioro hepático', '- alteración de conciencia;
- sangrado;
- ascitis;
- edema;
- ictericia progresiva;
- hipotensión;
- hipoglucemia;
- empeoramiento rápido de pruebas hepáticas/coagulación.

Requieren evaluación clínica oportuna.

---', 33)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('707b2b84-321f-50f3-9dd4-e957c504edd7', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_34', '18. TRASTORNOS DE LA VESÍCULA', '', 34)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('76170853-fa84-534a-a10b-7138988d37c6', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_35', 'Colelitiasis', 'Es la presencia de cálculos en la vesícula.

Merck, actualizado en febrero de 2026, señala que muchos cálculos son asintomáticos.

Cuando producen síntomas, el cuadro clásico es **cólico biliar**.

---', 35)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('bca8709b-503b-5c9e-88a0-56de4a4753c9', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_36', '19. Cólico biliar', 'Características posibles:

- dolor en cuadrante superior derecho o epigastrio;
- puede irradiar a espalda/hombro;
- puede aparecer tras comidas;
- náuseas/vómitos;
- suele resolverse cuando cesa la obstrucción transitoria.', 36)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('55213a36-ef66-582c-8d81-a408dcafeae7', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_37', 'Importante', 'Fiebre, ictericia, dolor persistente o deterioro sugieren complicación y no “cólico simple”.

---', 37)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1bd4e2ea-fb07-5de2-a5fb-73b15fd95f53', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_38', '20. Colecistitis aguda', 'Frecuentemente ocurre por obstrucción persistente del conducto cístico por un cálculo.

Puede presentar:

- dolor persistente en cuadrante superior derecho;
- fiebre;
- náuseas/vómitos;
- sensibilidad localizada;
- leucocitosis.', 38)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c199fae7-2684-5fe5-a5a7-372aaf00cdfa', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_39', 'Adultos mayores', 'Pueden mostrar síntomas menos específicos y ausencia de fiebre.

---', 39)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a7b20f9e-37be-51f4-bf61-e90e7d82223c', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_40', '21. Coledocolitiasis y colangitis', '', 40)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7e5125f4-bb08-52f8-9a71-b07d9503e6f7', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_41', 'Coledocolitiasis', 'Cálculo en vía biliar común.

Puede causar:
- ictericia;
- dolor;
- alteración de pruebas hepáticas;
- pancreatitis.', 41)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8248f3db-cbc1-5628-8a00-abcb16b16c21', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_42', 'Colangitis', 'Infección de vía biliar obstruida.

Puede evolucionar a:
- sepsis;
- shock.', 42)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ee060506-fb4e-5e93-b09d-3fd1d05f9838', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_43', 'Prioridad', 'Dolor biliar + fiebre + ictericia, especialmente con hipotensión o alteración mental, requiere atención urgente.

---', 43)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a832e542-f53f-503b-82cb-fb39cf5d226d', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_44', '22. Tratamiento de trastornos biliares', 'Puede incluir:

- analgesia;
- líquidos IV;
- antibióticos en infección;
- colecistectomía;
- ERCP si existe obstrucción del colédoco/colangitis;
- tratamiento de complicaciones.

La colelitiasis asintomática generalmente no requiere tratamiento quirúrgico rutinario.

---', 44)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4943d2d9-852e-58f5-bf0d-3b7195752fc0', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_45', '23. PANCREATITIS AGUDA', '', 45)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('df6714d2-97a5-53b7-8579-618e2e82c806', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_46', 'Concepto', 'La pancreatitis aguda es inflamación aguda del páncreas.

Causas frecuentes:

- cálculos biliares;
- alcohol.

Otras:
- hipertrigliceridemia;
- medicamentos;
- procedimientos;
- hipercalcemia;
- trauma;
- causas genéticas;
- idiopática.

---', 46)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ff4efd5a-8895-5b90-808e-0e6e395acd97', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_47', '24. Manifestaciones de pancreatitis aguda', 'Frecuentemente:

- dolor epigástrico intenso;
- puede irradiar a espalda;
- náuseas/vómitos;
- sensibilidad abdominal;
- distensión;
- taquicardia;
- fiebre.

En enfermedad grave:
- hipotensión;
- hipoxemia;
- insuficiencia renal;
- alteración de conciencia.

---', 47)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('77dde532-65dd-584a-bc6f-635eaee03ae2', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_48', '25. Diagnóstico de pancreatitis aguda', 'Clásicamente se establece cuando están presentes al menos **2 de 3**:

1. dolor abdominal compatible;
2. amilasa o lipasa ≥3 veces el límite superior normal;
3. imagen compatible.', 48)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7c7f65db-a9df-5910-a039-11577d5bec12', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_49', 'Clave', 'No es necesario que los tres estén presentes.

La lipasa es una prueba especialmente útil.

---', 49)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7352f8ec-336b-5e60-af6b-679d0b17df11', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_50', '26. Imagen en pancreatitis', 'La guía ACG 2024 recomienda:

- ultrasonido para valorar pancreatitis biliar;
- evitar TC rutinaria temprana solo para “medir gravedad” cuando el diagnóstico es claro;
- reservar TC para diagnóstico incierto o falta de mejoría en 48–72 horas, entre otros escenarios.

---', 50)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('59101c84-3c4c-58da-bea3-7c8ec60c5490', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_51', '27. Líquidos en pancreatitis', 'ACG 2024 recomienda una estrategia de **hidratación IV moderadamente agresiva**, con cristaloides isotónicos, y sugiere lactato de Ringer sobre solución salina normal.', 51)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c5c3be4b-0985-5168-a8f5-d21741446051', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_52', 'Muy importante', 'Debe individualizarse y reevaluarse.

Precaución en:
- insuficiencia cardiaca;
- enfermedad renal;
- adultos mayores;
- riesgo de sobrecarga.

No aplicar “litros fijos” a todos.

---', 52)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c7019246-9328-5e44-a004-de58e79f3c9c', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_53', '28. Nutrición en pancreatitis', 'En pancreatitis leve, la alimentación oral temprana según tolerancia es preferible al ayuno prolongado rutinario.

Cuando no se tolera oralmente y se requiere soporte:
- la nutrición enteral suele preferirse a parenteral.

---', 53)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('49ac84af-8fe0-526f-ba17-66bd89ec379d', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_54', '29. Antibióticos en pancreatitis', 'No se recomiendan antibióticos profilácticos de rutina para necrosis pancreática estéril.

Se utilizan cuando:
- existe infección;
- se sospecha infección;
- hay colangitis;
- otra indicación bacteriana.

---', 54)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('0a8bd5c5-c783-589f-a6c3-224db9c52b23', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_55', '30. ERCP en pancreatitis biliar', 'Puede requerirse de forma temprana cuando existe:
- pancreatitis biliar acompañada de colangitis;
- obstrucción biliar persistente en escenarios seleccionados.

No es un procedimiento automático para toda pancreatitis por cálculos.

---', 55)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d858f4e4-196a-5f25-9f80-889c4c0ca2a2', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_56', '31. Complicaciones de pancreatitis', '- necrosis;
- infección;
- colecciones/pseudoquistes;
- insuficiencia respiratoria;
- lesión renal aguda;
- shock;
- alteraciones metabólicas;
- falla multiorgánica.', 56)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6767ec61-84ab-58e4-a77c-3f293fcdd863', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_57', 'Enfermería', 'Monitorizar:
- signos vitales;
- respiración;
- diuresis;
- balance;
- dolor;
- glucemia;
- calcio/electrolitos;
- estado mental.

---', 57)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4555e9b1-dcd3-5a82-a2d0-7168bd796866', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_58', '32. DIABETES MELLITUS', '', 58)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('0928c05d-30d9-5968-89d4-167fafdf40d5', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_59', 'Tipos principales', '', 59)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('61bc9837-4a41-5339-b27e-d2c06d1d29e5', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_60', 'Tipo 1', 'Destrucción de células beta con deficiencia de insulina.

Generalmente requiere insulina de por vida.', 60)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1bf96867-02b7-53e4-b7ce-a76e55125b76', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_61', 'Tipo 2', 'Combinación de resistencia a insulina y deterioro progresivo de secreción.

El tratamiento es individualizado y puede incluir:
- estilo de vida;
- medicamentos no insulínicos;
- insulina.

---', 61)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('33fc969e-f6b6-51d9-b583-ede06a19945b', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_62', '33. Criterios diagnósticos ADA 2026', 'En adultos no embarazados, diabetes puede diagnosticarse por cualquiera de los siguientes criterios:

- **A1C ≥6.5%**;
- **glucosa plasmática en ayunas ≥126 mg/dL**;
- **glucosa a las 2 horas ≥200 mg/dL** durante OGTT con 75 g;
- **glucosa plasmática aleatoria ≥200 mg/dL** cuando existen síntomas clásicos de hiperglucemia o crisis hiperglucémica.', 62)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f080e2e8-4b38-5afb-b9c9-bfb714e24d42', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_63', 'Confirmación', 'Si no existe hiperglucemia inequívoca, el resultado debe confirmarse con una segunda prueba anormal conforme al estándar.

---', 63)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ccb65354-0441-5f90-bfa8-294815295723', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_64', '34. Manifestaciones de hiperglucemia', '- poliuria;
- polidipsia;
- visión borrosa;
- pérdida de peso;
- fatiga;
- infecciones recurrentes;
- deshidratación.

Algunas personas con tipo 2 pueden ser asintomáticas durante años.

---', 64)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b05ee6b5-a965-566b-be35-63c67d9a250a', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_65', '35. Valoración de la persona con diabetes', '- tipo/duración;
- medicamentos;
- alimentación;
- actividad;
- monitorización;
- episodios de hipoglucemia;
- A1C;
- presión arterial;
- lípidos;
- función renal;
- albuminuria;
- pies;
- visión;
- neuropatía;
- salud cardiovascular;
- técnica de inyección;
- capacidad de autocuidado;
- acceso económico;
- salud mental.

---', 65)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('3e5a8ea0-a336-59e2-87b7-c3900f89fbe8', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_66', '36. Hipoglucemia', 'ADA 2026 considera clínicamente importante una glucosa **<70 mg/dL (3.9 mmol/L)**.

Puede producir:

- temblor;
- sudoración;
- hambre;
- palpitaciones;
- irritabilidad;
- confusión;
- somnolencia;
- convulsiones;
- coma.', 66)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('766c128d-4d2b-5cf9-bd8a-e0d2563f7192', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_67', 'Prioridad', 'Confirmar glucosa si es posible sin retrasar tratamiento cuando el cuadro es evidente y grave.

---', 67)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('95cb7c0c-da87-5482-816f-1e4f525a4767', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_68', '37. Tratamiento de hipoglucemia', '', 68)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c65de625-2f24-54a2-9bb3-a4a7129b35e5', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_69', 'Persona consciente que puede tragar', 'Administrar carbohidrato de acción rápida según protocolo, reevaluar glucosa y repetir tratamiento si continúa baja.', 69)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('37d082ce-a54c-5344-bdfd-4e03b07b9967', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_70', 'Incapaz de tragar / inconsciente', 'No administrar alimentos o líquidos por boca.

Puede requerir:
- glucagón;
- glucosa IV;
- manejo de vía aérea;
- monitorización.', 70)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('80d30406-1942-5216-a5eb-a8698f967f14', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_71', 'Después', 'Investigar:
- exceso de insulina/medicamentos;
- ingesta insuficiente;
- ejercicio;
- alcohol;
- enfermedad renal;
- error de dosis.

---', 71)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('721fd9db-50f0-5163-b81e-d8fc258625da', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_72', '38. Seguridad con insulina', 'Antes de administrar:

- paciente correcto;
- tipo de insulina;
- dosis;
- horario;
- glucosa actual/tendencia;
- relación con comidas;
- estado clínico;
- cambios en función renal/nutrición;
- protocolo.', 72)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a340f8ea-f838-52e7-a08c-0091b0802ee7', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_73', 'Errores de alto riesgo', '- confundir concentraciones;
- confundir insulina rápida con basal;
- administrar prandial sin considerar si el paciente comerá;
- duplicar dosis;
- omitir verificación requerida.

La insulina se considera un medicamento de alto riesgo.

---', 73)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c7191b0d-5197-59cb-b623-5e5663caf3e0', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_74', '39. Insulina basal', 'La insulina basal cubre requerimientos entre comidas y durante la noche.', 74)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('dc770180-3689-5f4d-9d3c-43d9e236683c', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_75', 'Diabetes tipo 1', 'No debe suspenderse toda la insulina basal simplemente porque el paciente esté NPO; la ausencia absoluta de insulina puede precipitar cetoacidosis.

Los ajustes deben seguir prescripción/protocolo.

---', 75)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4e61c7a4-7663-5d3e-8596-2c1d2e4d16ef', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_76', '40. Tratamiento de diabetes tipo 2 — enfoque 2026', 'ADA 2026 recomienda un enfoque centrado en la persona considerando:

- eficacia;
- hipoglucemia;
- peso;
- enfermedad cardiovascular;
- insuficiencia cardiaca;
- enfermedad renal;
- hígado;
- costo;
- tolerabilidad;
- preferencias.

En personas con enfermedad cardiovascular, insuficiencia cardiaca o ERC, los beneficios de clases como SGLT2 y GLP-1 pueden influir en la elección independientemente del A1C.', 76)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b8f3c098-8de0-5869-a8b3-95702d419341', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_77', 'Regla', 'No enseñar “metformina siempre primero para todos” como una regla absoluta en 2026.

---', 77)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('0766b53c-d9b8-557c-a0a6-ddd8156130e4', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_78', '41. Cetoacidosis diabética (DKA)', 'Emergencia metabólica por déficit de insulina y cetosis.

Manifestaciones:

- poliuria/polidipsia;
- deshidratación;
- náuseas/vómitos;
- dolor abdominal;
- respiración de Kussmaul;
- aliento afrutado;
- alteración mental.

---', 78)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('391f2538-f7b6-5df2-b0a9-406d188bbdb1', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_79', '42. Criterios ADA 2026 para DKA', 'ADA 2026 resume tres componentes que deben estar presentes:

1. diabetes/hiperglucemia: glucosa ≥200 mg/dL **o antecedente de diabetes**;
2. cetosis significativa;
3. acidosis metabólica: pH <7.3 y/o bicarbonato <18 mmol/L.', 79)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('63545a9d-c0d5-5550-8284-508b8154245a', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_80', 'Actualización importante', 'La DKA puede ser **euglucémica**, especialmente en algunos pacientes con SGLT2, embarazo, baja ingesta u otros contextos.

Por eso una glucosa no extremadamente alta **no descarta DKA**.

---', 80)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('af4f3716-cc27-50ff-89ab-11822f8524eb', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_81', '43. Tratamiento de DKA', 'Principios:

- líquidos IV;
- insulina;
- corrección/vigilancia de potasio;
- tratamiento del desencadenante;
- monitorización frecuente;
- transición segura a insulina subcutánea cuando corresponda.', 81)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1d413a4f-e269-526d-aa06-b31c57264fa5', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_82', 'Potasio', 'Puede existir déficit corporal total aunque el potasio sérico inicial sea normal o alto.

La insulina puede bajar rápidamente K sérico.', 82)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1b0a0c3e-13cf-5e45-b21f-d435be0bf81f', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_83', 'Seguridad', 'Si existe hipopotasemia significativa, el manejo del potasio tiene prioridad antes de continuar ciertas fases de insulinoterapia según protocolo.

---', 83)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a6b1b205-1833-529c-a7c6-63a25cb436ee', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_84', '44. Estado hiperglucémico hiperosmolar (HHS)', 'Generalmente se caracteriza por:

- hiperglucemia muy marcada;
- hiperosmolalidad;
- deshidratación profunda;
- alteración neurológica;
- poca o ninguna cetosis significativa en comparación con DKA.

ADA 2026 utiliza glucosa plasmática **≥600 mg/dL** como uno de los criterios, junto con criterios de hiperosmolalidad y ausencia de cetosis/acidosis significativas.', 84)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('691bebb4-887d-58ee-9db0-314e9959ac98', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_85', 'Clave', 'DKA y HHS pueden coexistir.

---', 85)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7d58e42d-0677-5424-878c-b3afb94378d1', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_86', '45. Desencadenantes de crisis hiperglucémicas', '- infección;
- omisión de insulina;
- diagnóstico nuevo;
- infarto;
- ACV;
- pancreatitis;
- medicamentos;
- enfermedad aguda;
- acceso insuficiente a tratamiento.

---', 86)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('36a02488-eb82-563f-86a8-114184556cec', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_87', '46. Complicaciones crónicas de diabetes', '', 87)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('508e85fa-ac15-5cca-a863-b49b6489116d', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_88', 'Microvasculares', '- retinopatía;
- nefropatía;
- neuropatía.', 88)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('bb2bb735-4924-53d6-bc78-7ec6717aec7f', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_89', 'Macrovasculares', '- enfermedad coronaria;
- ACV;
- enfermedad arterial periférica.

Prevención:
- control glucémico individualizado;
- presión arterial;
- lípidos;
- no fumar;
- función renal;
- actividad;
- medicamentos cardioprotectores/renoprotectores cuando correspondan.

---', 89)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ed32fa99-1921-5329-904a-a7d805d19726', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_90', '47. Pie diabético', 'Valorar:

- piel;
- uñas;
- deformidades;
- temperatura;
- pulsos;
- sensibilidad protectora;
- calzado;
- heridas.

Educación:
- revisar pies diariamente;
- no caminar descalzo;
- no utilizar calor directo;
- calzado apropiado;
- consultar ante herida, cambio de color, edema o infección.

---', 90)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('02b571a3-8e91-5197-aa9e-464b3bb908d2', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_91', '48. Día de enfermedad', 'Educar según plan individual:

- continuar monitorización;
- hidratación;
- glucosa más frecuente;
- cetonas cuando esté indicado;
- no suspender insulina de forma arbitraria;
- saber cuándo llamar;
- buscar atención ante vómitos persistentes, cetonas, deshidratación, respiración anormal o alteración mental.

---', 91)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d40b59a7-00fa-5e71-8f4a-6c676a883a1d', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_92', '49. PAE', '', 92)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('14a15ffa-0c7a-529d-b14b-19dee95dae8c', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_93', 'Valoración', '- peso/IMC;
- estado hepático;
- dolor abdominal;
- hidratación;
- glucosa;
- medicamentos;
- función renal;
- laboratorios;
- educación/autocuidado.', 93)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ae9d65e0-2425-5ad3-89c8-eac553db4ccc', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_94', 'Diagnóstico/juicio', 'Problemas posibles:
- nutrición/metabolismo alterados;
- dolor;
- déficit de volumen;
- riesgo de glucemia inestable;
- conocimiento;
- riesgo de infección.', 94)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d3c8b0ea-9c51-5ed1-9291-ea1bbe7c0d4d', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_95', 'Planificación', 'Priorizar:
- hipoglucemia;
- DKA/HHS;
- sepsis/colangitis;
- pancreatitis grave;
- insuficiencia hepática;
- seguridad farmacológica.', 95)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('19415cb1-f946-57e2-9335-d00e3cf7e0dd', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_96', 'Implementación', '- monitorización;
- líquidos/medicamentos prescritos;
- nutrición;
- educación;
- prevención;
- coordinación.', 96)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5695cf8f-163f-5700-92a3-ef2e27fa0832', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_97', 'Evaluación', '- síntomas;
- glucosa;
- hidratación;
- función;
- laboratorios;
- comprensión;
- complicaciones.

---', 97)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('0c60aad2-c2de-5ecc-9abb-85cf100f2285', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_98', '50. Situaciones tipo examen', '', 98)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c154cd73-6e3f-55ab-b790-47814ad96a32', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_99', 'Caso 1 — Obesidad', 'Paciente con IMC 33 kg/m² pregunta si el número describe toda su salud.

**Respuesta:** no; IMC es herramienta de tamizaje y debe integrarse con comorbilidades, función y otros factores.', 99)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('0fbc1b32-1f43-5775-a6fc-f7d3aa342a30', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_100', 'Caso 2 — Hepatitis A', 'Paciente pregunta si HAV se volverá una infección crónica.

**Respuesta:** hepatitis A no produce infección crónica.', 100)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6a2f8e3e-1524-5911-86e0-e5ea922c2996', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_101', 'Caso 3 — Hepatitis B', 'Paciente HBsAg positivo requiere educación.

**Conducta:** explicar transmisión por sangre/fluidos, prevención, seguimiento y necesidad de interpretación serológica completa.', 101)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1c1c5049-392e-54aa-b8c3-5d9402d19b1f', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_102', 'Caso 4 — Dolor biliar', 'Paciente tiene dolor RUQ breve después de comida, sin fiebre ni ictericia.

**Interpretación:** compatible con cólico biliar, sujeto a evaluación.', 102)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2734876d-1c62-5a25-b1cb-5678c17ce27d', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_103', 'Caso 5 — Colangitis', 'Dolor RUQ + fiebre + ictericia, con hipotensión.

**Prioridad:** infección biliar complicada/sepsis; respuesta urgente.', 103)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('225e7467-ead0-5ac3-8a3e-26d4324f8f36', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_104', 'Caso 6 — Pancreatitis', 'Dolor epigástrico intenso hacia espalda y lipasa >3 veces normal.

**Interpretación:** cumple dos criterios clásicos compatibles con pancreatitis aguda.', 104)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('06bd0b31-c9bb-55a4-9ee7-531f390d6ad0', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_105', 'Caso 7 — Pancreatitis + falla renal', 'Paciente con pancreatitis tiene insuficiencia cardiaca y ERC.

**Conducta:** líquidos deben individualizarse y reevaluarse; evitar resucitación rígida excesiva.', 105)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('27c5e08e-b27a-5940-863d-9ad61b9a2026', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_106', 'Caso 8 — Glucosa diagnóstica', 'Paciente con poliuria/polidipsia tiene glucosa aleatoria 245 mg/dL.

**Interpretación:** cumple criterio diagnóstico ADA en presencia de síntomas clásicos.', 106)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('74895df6-e66f-5551-a817-ca6a3eff6fb8', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_107', 'Caso 9 — Hipoglucemia', 'Paciente consciente con glucosa 56 mg/dL, temblor y sudoración.

**Prioridad:** tratar hipoglucemia y reevaluar.', 107)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8002f654-2474-501c-a51f-14fa1adf6584', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_108', 'Caso 10 — Hipoglucemia inconsciente', 'Paciente no responde y tiene glucosa muy baja.

**Conducta:** no dar líquidos por boca; glucagón/glucosa IV según disponibilidad y protocolo.', 108)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('32da56f2-0995-567c-9fac-2e24ce4cb6e9', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_109', 'Caso 11 — DKA euglucémica', 'Paciente con diabetes en SGLT2 presenta náuseas, acidosis y cetonas con glucosa 180 mg/dL.

**Concepto:** una glucosa <200 no excluye DKA si existe antecedente de diabetes y criterios de cetosis/acidosis.', 109)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b1bd18be-292b-5fc7-8252-744880f45948', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_110', 'Caso 12 — Tipo 1 NPO', 'Paciente con diabetes tipo 1 queda NPO y alguien propone suspender toda insulina.

**Conducta:** no suspender automáticamente toda insulina basal; requiere ajuste protocolizado.

---', 110)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7ba38e31-306c-55ab-a45d-29b0f25be56f', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_111', '51. Errores frecuentes', '1. Tratar obesidad como simple falta de voluntad.
2. Usar IMC como valoración completa.
3. Confundir transmisión HAV y HBV.
4. Decir que hepatitis A se vuelve crónica.
5. Ignorar ictericia + fiebre + dolor biliar.
6. Dar líquidos agresivos sin reevaluación en pancreatitis.
7. Usar antibióticos profilácticos en necrosis pancreática estéril.
8. Mantener NPO prolongado de rutina en pancreatitis leve.
9. Diagnosticar diabetes por una sola prueba sin confirmación cuando no hay hiperglucemia inequívoca.
10. Dar alimentos por boca a paciente hipoglucémico inconsciente.
11. Suspender toda insulina en diabetes tipo 1 NPO.
12. Descartar DKA porque la glucosa no es extremadamente alta.
13. Corregir glucosa sin vigilar potasio en DKA.
14. Enseñar un único fármaco como tratamiento universal de diabetes tipo 2.

---', 111)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('80e64667-52bb-57ee-8bd0-e3b800d840b2', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_112', '52. Qué memorizar', '**Obesidad = enfermedad crónica y multifactorial.**

**IMC adulto: ≥25 sobrepeso; ≥30 obesidad (OMS).**

**HAV = fecal-oral + aguda + vacuna + no crónica.**

**HBV = sangre/fluidos + aguda o crónica + vacuna.**

**Colecistitis = dolor RUQ persistente ± fiebre.**

**Colangitis = obstrucción biliar + infección → riesgo de sepsis.**

**Pancreatitis: dolor compatible + lipasa/amilasa ≥3× + imagen; se requieren 2 de 3.**

**Diabetes ADA 2026: A1C ≥6.5%; ayuno ≥126; 2h OGTT ≥200; aleatoria ≥200 + síntomas/crisis.**

**Hipoglucemia: <70 mg/dL es clínicamente importante.**

**DKA puede ser euglucémica.**

**Tipo 1 NPO: no suspender automáticamente toda insulina basal.**

---', 112)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f71a04fe-3c27-58c9-a30f-afbde5186217', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_113', '53. Fuentes y validación', '', 113)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5ece4ec9-0f03-5052-b190-9dc338f11866', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_114', 'Fuente rectora', '**CICDE Panamá. Lineamientos para el Examen de Competencias de Profesionales de Enfermería, 2026.**', 114)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a475c6b4-4698-5cff-aa31-93a973616f9b', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_115', 'Fuentes CICDE', '**Hinkle, J. L.; Cheever, K. H. Brunner y Suddarth. Enfermería Médicoquirúrgica. 14.ª edición, 2019.**

**Potter, P. A. et al. Fundamentos de Enfermería. 11.ª edición, 2023.**', 115)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d35247e0-dcd3-51fd-beac-bafc8ee83ad0', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_116', 'Obesidad', '**World Health Organization. Obesity and overweight. Actualizado 8 de diciembre de 2025.**', 116)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c5bf8899-c94e-5d6f-9f8d-aaaef325b716', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_117', 'Hepatitis A/B', '**CDC. Clinical Overview of Hepatitis A. Actualizado 29 de agosto de 2025.**

**CDC. Clinical Overview of Hepatitis B. Actualizado 29 de agosto de 2025.**

**CDC. Clinical Care of Hepatitis B. 2025.**', 117)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('7d72f9d0-1c8f-591f-8b83-1d1843053fa1', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_118', 'Vesícula', '**Merck Manual Professional Edition. Cholelithiasis. Actualizado febrero de 2026.**

**Merck Manual Professional Edition. Acute Cholecystitis. Revisión 2025–2026.**', 118)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8be676b6-72d3-5f6b-9342-64cece6d51a6', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_119', 'Pancreatitis', '**American College of Gastroenterology. Clinical Guideline: Management of Acute Pancreatitis. 2024.**', 119)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('da5c65fd-24d1-5c35-89fd-e4dcda24e5ad', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_120', 'Diabetes', '**American Diabetes Association. Standards of Care in Diabetes—2026.**

Secciones utilizadas:
- Diagnosis and Classification of Diabetes;
- Glycemic Goals, Hypoglycemia, and Hyperglycemic Crises;
- Pharmacologic Approaches to Glycemic Treatment;
- Diabetes Care in the Hospital.

---', 120)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ca65e5ec-7157-5a87-acde-86c07ad19820', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_121', '54. Control de calidad', 'Este paquete:
- cubre los cuatro subtemas exactos del CICDE;
- utiliza OMS 2025 para obesidad;
- CDC 2025 para hepatitis A/B;
- Merck 2026 para litiasis biliar;
- ACG 2024 para pancreatitis;
- ADA Standards of Care 2026 para diabetes;
- incorpora DKA euglucémica;
- evita dosis universales y esquemas farmacológicos rígidos;
- contiene 12 casos originales.

---', 121)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('dcd9f0c0-036f-5813-bcf3-09dc3eec988e', 'f61dd8d3-5098-5b6a-bf5b-1e344e7c8c61', 'sec_122', '55. Estado para integración', '**Estado recomendado:** `REVIEW`

Antes de `VERIFIED`:
- registrar `reviewed_by` y `reviewed_at`;
- vincular fuentes;
- cruzar el esquema nacional de vacunación Panamá 2026 para hepatitis A/B;
- confirmar protocolos nacionales/institucionales si se enseñan regímenes de insulina o tratamiento hepatológico específicos;
- enlazar con ADULT-04, ADULT-09, ADULT-17, ADULT-21, ADULT-23 y Farmacología.', 122)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9490184c-ad5d-5076-bc81-301ea9425d3b', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_1', 'Función renal y urinaria', '**Área:** Salud del Adulto  
**Código:** ADULT-23  
**Estado académico del paquete:** `REVIEW`  
**Última revisión del paquete:** 2026-09-10

---', 1)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('dfef9240-5ce3-5930-8370-2b9f77f62b4d', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_2', '1. Alcance oficial CICDE', 'El lineamiento CICDE 2026 incluye expresamente:

1. Insuficiencia renal y tratamiento.
2. Infecciones de las vías urinarias e incontinencia.
3. Sondaje.
4. Urolitiasis o nefrolitiasis.

Para preparación completa se abordan tanto lesión renal aguda como enfermedad renal crónica, ya que “insuficiencia renal” puede presentarse clínicamente en ambos contextos.

---', 2)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('237f6010-9ff7-505c-a582-b12e4907ba35', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_3', '2. Objetivos de aprendizaje', 'El estudiante debe poder:

1. Explicar funciones básicas del riñón.
2. Valorar función renal mediante creatinina, eGFR, diuresis, electrolitos y albuminuria.
3. Diferenciar lesión renal aguda y enfermedad renal crónica.
4. Reconocer causas prerrenales, intrínsecas y posrenales de AKI.
5. Identificar hiperpotasemia, edema pulmonar, acidosis y uremia como complicaciones graves.
6. Comprender indicaciones generales de terapia de reemplazo renal.
7. Reconocer manifestaciones de cistitis y pielonefritis.
8. Aplicar principios actuales de tratamiento de UTI complicada.
9. Diferenciar bacteriuria asintomática de UTI sintomática.
10. Diferenciar incontinencia de urgencia, esfuerzo, rebosamiento y funcional.
11. Realizar cuidados seguros de sonda urinaria.
12. Prevenir CAUTI.
13. Reconocer cólico renal y obstrucción infectada como emergencia urológica.
14. Educar en prevención de recurrencia de cálculos.
15. Resolver casos tipo CICDE.

---', 3)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b1c3215a-db75-5d6f-9f40-19603d6852a2', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_4', '3. Funciones del riñón', 'Los riñones participan en:

- eliminación de desechos;
- regulación de agua;
- sodio;
- potasio;
- equilibrio ácido-base;
- presión arterial;
- producción de eritropoyetina;
- metabolismo de vitamina D;
- homeostasis mineral.

---', 4)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1a543f87-2334-556c-89b6-b16415aab163', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_5', '4. Valoración renal', '', 5)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4b93f625-0376-5b8f-a402-9d7fccbe7ec4', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_6', 'Historia', '- diuresis;
- cambios de color/espuma;
- hematuria;
- disuria;
- urgencia;
- frecuencia;
- nocturia;
- dolor lumbar/flanco;
- medicamentos;
- diabetes;
- hipertensión;
- infecciones;
- cirugía/contraste;
- pérdidas de volumen;
- antecedentes de cálculos.', 6)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('28301b7e-f36b-5237-9ce1-fe66b33a5991', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_7', 'Examen', '- presión arterial;
- peso;
- edema;
- hidratación;
- perfusión;
- pulmones;
- vejiga/distensión;
- estado mental;
- piel.

---', 7)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6a224a65-3490-520b-9efe-22e08b06d2bb', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_8', '5. Laboratorios clave', '', 8)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b7d01940-2964-53fd-be25-6bed2a138a70', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_9', 'Creatinina', 'Marcador indirecto de filtración.

Puede verse influida por:
- masa muscular;
- edad;
- producción;
- medicamentos;
- estado agudo.', 9)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('dc9e9486-6405-5cb8-898e-42843391fb28', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_10', 'eGFR', 'Estimación de filtración glomerular.

En AKI puede ser menos fiable para describir cambios rápidos.', 10)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8c7d26de-4556-5998-bf1a-d1524ddee7bc', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_11', 'Albuminuria', 'Importante marcador de daño renal y riesgo cardiovascular/renal.', 11)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('eb2b8a60-c83c-5287-ba08-8cccc4fce000', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_12', 'Electrolitos', 'Especialmente:
- potasio;
- sodio;
- bicarbonato;
- calcio;
- fósforo.

---', 12)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d472530a-8296-5a6d-afff-253a6584f664', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_13', '6. Diuresis', 'Una caída importante de diuresis puede ser señal de:
- hipovolemia;
- shock;
- AKI;
- obstrucción;
- falla cardiaca;
- otras causas.', 13)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('65cc9b81-5c6b-5b2d-a4eb-9c06b5200671', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_14', 'Clave', 'La ausencia de oliguria **no descarta AKI**.

---', 14)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('651d1d18-7a6e-547a-afd9-447c5571a53d', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_15', '7. LESIÓN RENAL AGUDA (AKI)', 'Merck 2026 define AKI como una disminución rápida de función renal a lo largo de días o semanas, con acumulación de productos nitrogenados y, en algunos casos, disminución de diuresis.

Puede causar rápidamente alteraciones:
- de líquidos;
- electrolitos;
- ácido-base.

---', 15)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8a91f161-c91e-5900-8367-6d9ad0529dde', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_16', '8. Clasificación etiológica de AKI', '', 16)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('27c79106-8216-5e17-8075-dab105ca4cc0', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_17', 'Prerrenal', 'Disminución de perfusión renal sin lesión estructural inicial.

Ejemplos:
- hipovolemia;
- hemorragia;
- sepsis;
- bajo gasto cardiaco.', 17)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d301ec15-f7f3-59a4-8d45-b62974c60fad', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_18', 'Intrínseca', 'Daño del parénquima renal.

Ejemplos:
- necrosis tubular;
- glomerulonefritis;
- nefritis intersticial;
- enfermedad vascular.', 18)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c7c59659-fd8a-5ea4-b11a-07ee8738bce2', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_19', 'Posrenal', 'Obstrucción del flujo urinario.

Ejemplos:
- próstata;
- cálculos;
- tumor;
- obstrucción bilateral.

---', 19)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('bcbfef81-504e-5266-bd97-2a3f3721964b', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_20', '9. Prevención y manejo inicial de AKI', '- identificar causa;
- optimizar perfusión;
- evitar sobrecarga;
- revisar nefrotóxicos;
- ajustar medicamentos a función renal;
- tratar infección/shock;
- aliviar obstrucción;
- monitorizar creatinina;
- diuresis;
- electrolitos;
- ácido-base;
- peso.', 20)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('bd98bdd0-f75b-51a2-ace9-bc9b94bd8964', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_21', 'Importante', '“Dar líquidos” no es tratamiento universal de AKI. En sobrecarga o falla cardiaca puede empeorar al paciente.

---', 21)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e3c8192f-9cb1-5ed4-88d1-6305449cfc37', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_22', '10. Complicaciones graves de AKI', '- hiperpotasemia;
- acidosis metabólica;
- edema pulmonar;
- uremia;
- encefalopatía;
- pericarditis;
- sobrecarga;
- alteraciones de sodio;
- toxicidad de medicamentos.

---', 22)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ca9a5f6f-8399-594e-b0b3-6aef84b76e02', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_23', '11. Hiperpotasemia', 'Puede provocar arritmias potencialmente mortales.

Valorar:
- K;
- ECG;
- función renal;
- medicamentos;
- diuresis;
- hemólisis de muestra.

Tratamiento urgente puede incluir, según situación:
- estabilización cardiaca con calcio;
- desplazamiento intracelular de K con insulina/glucosa y otras medidas;
- eliminación de K;
- diálisis.', 23)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('11d15542-ed5c-5c8e-a667-2d7399a5a430', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_24', 'Clave', 'El calcio estabiliza membrana cardiaca, pero **no elimina potasio del organismo**.

---', 24)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('0b55c8a5-d29a-56c6-bb45-53d06c088be8', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_25', '12. Terapia de reemplazo renal', 'Puede ser necesaria cuando las complicaciones no responden adecuadamente al tratamiento médico.

Indicaciones clínicas generales incluyen:

- hiperpotasemia refractaria o grave;
- acidosis severa refractaria;
- sobrecarga/edema pulmonar refractario;
- complicaciones urémicas;
- determinadas intoxicaciones;
- otras situaciones individualizadas.', 25)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f00b62b0-12aa-592e-8ae2-a9aefe27ff04', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_26', 'Regla', 'No se inicia diálisis solo por una creatinina aislada.

---', 26)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('05482c57-52f0-5ec8-8d78-a112eb8311f7', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_27', '13. Hemodiálisis', 'La sangre circula a través de un dializador.

Requiere acceso:
- fístula arteriovenosa;
- injerto;
- catéter venoso en determinados contextos.

Cuidados:
- peso antes/después;
- presión;
- acceso;
- sangrado;
- infección;
- hipotensión;
- electrolitos;
- síntomas.

---', 27)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('fe71be8a-eeac-5de0-9fd3-4a8a1fc32338', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_28', '14. Fístula arteriovenosa', 'Valorar:

- frémito (thrill);
- soplo (bruit);
- piel;
- infección;
- perfusión distal.', 28)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('38eba9d7-40f7-55cd-be11-f65464deaa0d', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_29', 'Proteger extremidad', 'Evitar:
- presión arterial;
- venopunciones;
- compresión innecesaria;
- ropa muy apretada.', 29)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9dc320ef-e59b-5f62-9d58-ea9342ca79c6', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_30', 'Alarma', 'Ausencia de thrill/bruit requiere valoración urgente por posible trombosis.

---', 30)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9f4fb775-28d9-5d4d-b212-e3d68cb564d2', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_31', '15. Diálisis peritoneal', 'Utiliza el peritoneo como membrana de intercambio.

Vigilar:
- técnica aséptica;
- entrada/salida;
- aspecto del efluente;
- dolor;
- fiebre;
- glucosa;
- balance;
- sitio del catéter.', 31)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d5f6655d-44d8-5579-9863-74884beb31de', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_32', 'Alarma', '**Efluente turbio + dolor abdominal** sugiere peritonitis hasta evaluación.

---', 32)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('897b4502-18ca-5ffb-b2ca-26ae368d3066', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_33', '16. ENFERMEDAD RENAL CRÓNICA (CKD/ERC)', 'KDIGO 2024 sigue siendo el estándar global vigente en 2026 para evaluación y manejo de CKD.

ERC implica alteraciones de estructura o función renal presentes durante **≥3 meses**, con implicaciones para la salud.

Puede clasificarse por:
- causa;
- categoría de eGFR;
- categoría de albuminuria.

---', 33)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('109ca853-b153-558c-8caf-5903f69423ad', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_34', '17. Factores y causas frecuentes de ERC', '- diabetes;
- hipertensión;
- glomerulopatías;
- enfermedades hereditarias;
- enfermedad vascular;
- obstrucción;
- otras.', 34)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e56f5849-c389-58ea-a046-a7b40482e176', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_35', 'Prevención', 'Control de diabetes y presión arterial, reducción de riesgo cardiovascular y uso apropiado de terapias renoprotectoras.

---', 35)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a46ea02b-d323-59b5-a4e6-6029e271603d', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_36', '18. Manifestaciones de ERC avanzada', '- fatiga;
- anorexia;
- náuseas;
- prurito;
- edema;
- alteraciones del sueño;
- neuropatía;
- cambios cognitivos;
- calambres;
- disnea;
- anemia;
- alteraciones minerales.

Muchos pacientes son asintomáticos en fases iniciales.

---', 36)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('0acbfe58-6fd1-5d02-b2a6-678ebf3292d3', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_37', '19. Complicaciones de ERC', '- anemia;
- hiperpotasemia;
- acidosis;
- sobrecarga;
- hipertensión;
- trastorno mineral y óseo;
- enfermedad cardiovascular;
- desnutrición;
- uremia.

---', 37)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('61aced36-07f8-5a29-841c-08184d15894d', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_38', '20. Medicamentos y función renal', 'La función renal puede requerir:

- ajuste de dosis;
- evitar determinados nefrotóxicos;
- vigilancia de potasio;
- revisión de AINE;
- cuidado con contraste según riesgo;
- conciliación frecuente.', 38)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4e913cd7-3b73-54b8-91e9-1d9b5af4584b', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_39', 'Error', 'Asumir que una dosis habitual es segura en ERC avanzada.

---', 39)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f8cd93ec-9343-5c33-bbf3-fbf9cb9d25b0', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_40', '21. INFECCIÓN URINARIA', 'Puede afectar:

- uretra;
- vejiga;
- próstata;
- riñón.', 40)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('3a1d9b45-684f-59b3-9106-8554a73b4a02', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_41', 'Cistitis', 'Puede causar:
- disuria;
- urgencia;
- frecuencia;
- dolor suprapúbico;
- hematuria.', 41)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('30f9e537-0149-5c40-997b-b5f61721c2b4', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_42', 'Pielonefritis', 'Puede causar:
- fiebre;
- escalofríos;
- dolor en flanco;
- náuseas/vómitos;
- malestar;
- síntomas urinarios.

---', 42)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1a4eeaef-5fa5-5d88-8f7a-1f5342f5c0ca', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_43', '22. UTI complicada — actualización IDSA 2025', 'IDSA publicó en julio de 2025 su primera guía específica para **UTI complicada**.

Su enfoque para antibiótico empírico considera:

1. gravedad de enfermedad;
2. riesgo de microorganismo resistente;
3. factores propios del paciente;
4. antibiograma local reciente cuando existe sepsis.', 43)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1712f896-351e-5137-a26a-7d0ff5a27963', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_44', 'Después del cultivo', 'Debe favorecerse tratamiento dirigido al microorganismo y sensibilidad, evitando espectro amplio innecesario.

---', 44)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('42f4974b-6f41-5efa-aa7d-908bb46d3079', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_45', '23. UTI y sepsis', 'Signos de alarma:

- hipotensión;
- alteración mental;
- taquipnea;
- fiebre/hipotermia;
- oliguria;
- lactato elevado cuando se mide;
- deterioro general.', 45)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('16cfce63-3345-50b7-b7f2-cf287f296076', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_46', 'Prioridad', 'Pielonefritis/UTI complicada con sepsis requiere evaluación y antibiótico oportuno según protocolo.

---', 46)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('371f4fc5-3473-565e-a34e-11d9bb462d96', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_47', '24. Bacteriuria asintomática', 'Bacterias en orina sin síntomas urinarios no equivalen automáticamente a UTI que requiera antibiótico.

En general, el tratamiento rutinario se evita, con excepciones importantes como:
- embarazo;
- antes de determinados procedimientos urológicos invasivos.', 47)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b8e98bbe-5028-5fad-9005-a9c4627a3f8f', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_48', 'Clave', 'No tratar únicamente “un cultivo positivo” sin contexto.

---', 48)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4f2f2c9c-128d-59ed-8b62-fb69c7453ed1', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_49', '25. INCONTINENCIA URINARIA', 'La pérdida involuntaria de orina requiere identificar tipo y causa.', 49)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5ce9b702-e072-55c8-bfdc-8aca73ac4760', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_50', 'De esfuerzo', 'Escape con:
- tos;
- risa;
- ejercicio;
- aumento de presión abdominal.', 50)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('95f64b15-16b7-58ee-9407-5eb8264b395c', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_51', 'De urgencia', 'Urgencia súbita seguida de escape.', 51)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('29ae6fb6-0368-54d1-8527-0f04e56f6a74', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_52', 'Por rebosamiento', 'Retención con vaciamiento incompleto y goteo.', 52)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('94ab8ff0-7d6f-5687-a344-d200bf1f4c07', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_53', 'Funcional', 'La persona podría controlar vejiga, pero barreras:
- movilidad;
- cognición;
- ambiente;
- acceso al baño

impiden llegar a tiempo.', 53)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('63b8732e-6159-5aac-af89-4014b8e5748b', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_54', 'Mixta', 'Combinación, frecuentemente esfuerzo + urgencia.

---', 54)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('532b5fa6-0dbc-5a23-a53e-1bb202cac77b', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_55', '26. Valoración de incontinencia', '- inicio;
- patrón;
- frecuencia;
- nocturia;
- urgencia;
- disuria;
- medicamentos;
- movilidad;
- cognición;
- estreñimiento;
- diabetes;
- historia urológica;
- volumen residual cuando está indicado;
- diario miccional.', 55)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5d3a777c-6603-578b-a0d6-6a2598d92481', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_56', 'Clave', 'La incontinencia no debe considerarse una consecuencia “normal e inevitable” de la edad.

---', 56)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('581417d5-5f36-5371-9bfe-71dc44f1848f', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_57', '27. Intervenciones para incontinencia', 'Dependiendo del tipo:

- entrenamiento vesical;
- micción programada;
- fortalecimiento de piso pélvico;
- manejo de líquidos individualizado;
- tratar infección/estreñimiento;
- revisar medicamentos;
- facilitar acceso al baño;
- dispositivos o fármacos seleccionados;
- tratamiento urológico cuando corresponda.

---', 57)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('460d010c-6b8f-5f96-b766-a4ad1519d4c6', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_58', '28. Retención urinaria', 'La retención aguda puede causar:

- dolor suprapúbico;
- distensión vesical;
- incapacidad para orinar;
- inquietud.

NIDDK señala que la retención aguda requiere drenaje inmediato de vejiga mediante catéter.

Después debe investigarse la causa.

---', 58)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a7566b2c-467d-5dc0-9ece-aafdf3480878', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_59', '29. SONDAJE URINARIO', 'El sondaje puede ser:

- intermitente;
- permanente/indwelling;
- suprapúbico en contextos específicos.', 59)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c5ace8b5-7af4-5cdc-9e70-967d70c2bcb0', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_60', 'Principio de seguridad', '**Usar sonda únicamente cuando está indicada y retirarla tan pronto deje de ser necesaria.**

---', 60)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('eb25dde3-6bd0-53a0-bb1f-d81cfcbf12b9', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_61', '30. Indicaciones apropiadas de sonda permanente', 'Pueden incluir:

- retención/obstrucción;
- medición exacta de diuresis en ciertos pacientes críticos;
- algunas cirugías;
- asistencia para cicatrización de heridas sacras/perineales seleccionadas en paciente incontinente;
- inmovilización prolongada seleccionada;
- confort al final de vida cuando beneficia al paciente.', 61)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5ac9fb03-b025-5ae5-9b42-20137792db7e', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_62', 'No usar rutinariamente', 'Solo para:
- comodidad del personal;
- incontinencia sin otra indicación;
- obtener muestra cuando existen alternativas.

---', 62)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('bc583287-a29f-5ba4-89e6-e0ae645cad49', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_63', '31. Inserción segura de sonda — prevención CAUTI', 'CDC recomienda:

- solo personal entrenado;
- higiene de manos;
- técnica aséptica;
- equipo estéril;
- catéter de menor calibre compatible con drenaje adecuado;
- fijación correcta;
- sistema cerrado.

---', 63)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('fef7fceb-b697-5939-a6dc-d63c33e58959', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_64', '32. Mantenimiento de sonda', '- mantener flujo sin obstrucción;
- bolsa por debajo de nivel vesical;
- bolsa nunca en el piso;
- evitar acodamientos;
- vaciar con técnica limpia;
- evitar desconexiones;
- higiene perineal rutinaria;
- revisar necesidad diariamente.', 64)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('766347af-dba3-56af-a898-d5fab989aa5e', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_65', 'Clave', 'No cambiar sonda o bolsa a intervalos fijos de forma rutinaria si no existe una indicación clínica/institucional.

---', 65)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ca584847-5367-59a0-8c1d-9c5986eb17fb', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_66', '33. Prevención de CAUTI', 'CDC 2025 recuerda que una gran proporción de UTI hospitalarias se relacionan con sonda.

La prevención más efectiva incluye:

- evitar sondas innecesarias;
- inserción estéril;
- mantener sistema cerrado;
- retirar precozmente.

---', 66)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('de3a3334-921a-52a9-ae7a-28ea4308acd0', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_67', '34. Muestra de orina en paciente sondado', 'Para cultivo:
- obtener de puerto de muestreo desinfectado según técnica;
- no obtener de la bolsa recolectora para cultivo rutinario.

Seguir protocolo institucional.

---', 67)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6be8e762-37b2-5035-9d1b-e4ca24f66401', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_68', '35. UROLITIASIS / NEFROLITIASIS', 'Los cálculos urinarios son depósitos sólidos formados en el aparato urinario.

Tipos frecuentes:
- calcio;
- ácido úrico;
- estruvita;
- cistina.

El manejo depende de:
- tamaño;
- localización;
- composición;
- obstrucción;
- infección;
- función renal.

---', 68)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ed91b0fa-fb9f-51c8-a24c-34dd6ca377a1', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_69', '36. Cólico renal', 'Manifestaciones:

- dolor intenso en flanco;
- puede irradiar a abdomen inferior/ingle;
- inquietud;
- náuseas/vómitos;
- hematuria.

El paciente frecuentemente cambia de posición buscando alivio.

---', 69)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('edc2e87a-a46e-5276-96da-ec129eda7f86', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_70', '37. Diagnóstico de cálculos', 'Puede incluir:

- examen de orina;
- creatinina;
- hemograma;
- imágenes;
- análisis del cálculo cuando se recupera.

Merck señala que TC sin contraste es una modalidad diagnóstica frecuente en adultos.

---', 70)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('19c25310-d8ef-580a-b3b1-16b734e6fde7', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_71', '38. Obstrucción + infección = emergencia', '', 71)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a8878092-647a-57d4-956e-c23ac442a255', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_72', 'Señales críticas', 'Cálculo/obstrucción con:
- fiebre;
- sepsis;
- anuria;
- lesión renal;
- riñón único comprometido;
- dolor/vómito intratables

requiere evaluación urológica urgente.', 72)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('60cafdf5-179c-52d5-afa8-e5a61b799888', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_73', 'Clave', 'Un sistema urinario obstruido e infectado puede necesitar **drenaje urgente**, además de antibióticos.

---', 73)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('3d239068-19db-5cac-ae41-847e155b7ee7', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_74', '39. Tratamiento del cólico renal', 'Puede incluir:

- analgesia;
- antieméticos;
- hidratación apropiada;
- terapia expulsiva en pacientes seleccionados;
- procedimientos urológicos.', 74)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b9865d61-a4ca-50c1-90e7-b0b1ece80f9d', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_75', 'Importante', 'No “forzar litros de agua” durante una obstrucción aguda dolorosa como tratamiento mecánico para empujar el cálculo.

---', 75)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2c546831-1818-5982-8dc4-e55194ea3d6a', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_76', '40. Prevención de recurrencia', 'NIDDK recomienda:

- hidratación suficiente individualizada;
- agua como bebida principal;
- evaluación del tipo de cálculo;
- cambios dietéticos según composición/riesgo;
- reducción de sodio en muchos pacientes;
- evitar restricciones de calcio indiscriminadas;
- medicamentos específicos cuando están indicados.', 76)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1a8dc40a-7d43-53da-882c-8232d625447f', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_77', 'Enfermedad renal/cardiaca', 'El volumen de líquidos debe individualizarse.

---', 77)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c5182e2e-e54a-5191-8eda-541512baf39f', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_78', '41. Educación del paciente renal', '- conocer función renal;
- evitar automedicación nefrotóxica;
- adherencia;
- controlar presión/glucosa;
- registrar peso si está indicado;
- reconocer edema/disnea;
- cuidado de acceso de diálisis;
- dieta/líquidos individualizados;
- signos de UTI;
- signos de obstrucción;
- seguimiento.

---', 78)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('17253790-8602-5a33-9676-554cccbdfc8d', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_79', '42. PAE renal y urinario', '', 79)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e15fc3dc-fc14-5053-a854-74a1c91ef64e', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_80', 'Valoración', '- diuresis;
- peso;
- presión;
- edema;
- pulmones;
- creatinina/eGFR;
- electrolitos;
- síntomas urinarios;
- acceso/dispositivos.', 80)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c43c6d3f-ea6c-505f-b1ff-b267a86baf6c', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_81', 'Diagnóstico/juicio', '- eliminación alterada;
- exceso/déficit de volumen;
- riesgo de infección;
- riesgo electrolítico;
- conocimiento;
- dolor.', 81)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b397c7bf-9631-57f9-a17e-17f765f67aa2', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_82', 'Planificación', 'Priorizar:
- hiperpotasemia;
- edema pulmonar;
- sepsis;
- obstrucción;
- uremia;
- seguridad de dispositivos.', 82)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b2bd8f30-51aa-5e91-b4f9-7830f562bc9c', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_83', 'Implementación', '- balance;
- medicamentos ajustados;
- cuidados de acceso;
- catéter seguro;
- prevención de infección;
- educación.', 83)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f0e326b9-7661-5b1a-885e-a4f11bc290bb', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_84', 'Evaluación', '- diuresis;
- peso;
- respiración;
- electrolitos;
- infección;
- función renal;
- síntomas.

---', 84)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('03de36ae-78e4-5d66-9651-aa10c23996e8', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_85', '43. Situaciones tipo examen', '', 85)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8a7d6008-ad5c-530e-aeeb-4bcf80c6e3ee', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_86', 'Caso 1 — AKI', 'Paciente séptico desarrolla aumento de creatinina y caída de diuresis.

**Prioridad:** identificar AKI, perfusión, sepsis, medicamentos y complicaciones.', 86)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('66900748-3d25-58f7-9938-4851e17a7ef8', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_87', 'Caso 2 — AKI con edema', 'Paciente con AKI presenta disnea y crepitantes.

**Conducta:** valorar sobrecarga/edema pulmonar; no administrar líquidos automáticamente.', 87)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('0c0efdb7-009e-5cc1-bd93-d9502c6a02d8', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_88', 'Caso 3 — Hiperpotasemia', 'Paciente renal tiene K alto y cambios ECG.

**Prioridad:** emergencia; estabilización cardiaca y reducción/eliminación de K según protocolo.', 88)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('817151d7-c83a-51b1-b1d3-6ea3809e46ea', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_89', 'Caso 4 — Fístula', 'No se palpa thrill en fístula AV.

**Conducta:** notificar urgentemente; sospechar pérdida de permeabilidad.', 89)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1eb9f53c-129c-5bc1-a3bf-090c1188e104', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_90', 'Caso 5 — Diálisis peritoneal', 'Efluente turbio y dolor abdominal.

**Sospecha:** peritonitis.', 90)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b2af227d-1759-5469-a9c4-13b584150632', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_91', 'Caso 6 — Cistitis', 'Disuria, urgencia y frecuencia sin signos sistémicos.

**Interpretación:** cuadro compatible con infección urinaria baja.', 91)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5fefff83-bcaf-58e7-bec1-28996636dc28', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_92', 'Caso 7 — Pielonefritis', 'Fiebre, escalofríos, dolor en flanco y vómitos.

**Interpretación:** posible infección urinaria alta; valorar gravedad/sepsis.', 92)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f128c00f-d1f0-5028-bfd9-63d22c6407b0', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_93', 'Caso 8 — Cultivo positivo sin síntomas', 'Paciente no embarazado, estable, sin síntomas urinarios tiene bacteriuria.

**Conducta:** no asumir automáticamente necesidad de antibiótico.', 93)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('872173d5-8859-5eb0-9b5a-637f022b0102', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_94', 'Caso 9 — Incontinencia', 'Paciente pierde orina al toser.

**Tipo:** esfuerzo.', 94)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f4423928-e1e3-5144-bcde-e38d07baafbc', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_95', 'Caso 10 — Sonda', 'Paciente sondado por comodidad desde hace días sin indicación.

**Conducta:** revisar y retirar si ya no existe indicación.', 95)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5e6c413d-2e29-5042-add6-e1e14c111968', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_96', 'Caso 11 — Cálculo con fiebre', 'Cólico renal + fiebre + hipotensión.

**Prioridad:** posible obstrucción infectada/sepsis; emergencia urológica.', 96)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('22773e73-0808-5d09-b7cf-89e62b428289', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_97', 'Caso 12 — Cálculo', 'Paciente quiere beber grandes volúmenes rápidamente para “empujar” un cálculo obstructivo.

**Educación:** no forzar líquidos; hidratación debe ser apropiada al estado clínico.

---', 97)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('16cd2a06-dade-5ec9-9768-478f06eeb8ae', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_98', '44. Errores frecuentes', '1. Definir función renal solo con creatinina.
2. Descartar AKI porque hay diuresis.
3. Dar líquidos a todo AKI.
4. Iniciar diálisis únicamente por una cifra de creatinina.
5. Aplicar presión arterial en brazo con fístula AV.
6. Ignorar efluente peritoneal turbio.
7. Tratar todo cultivo positivo como UTI.
8. Confundir incontinencia de rebosamiento con urgencia.
9. Mantener sonda sin indicación.
10. Romper sistema cerrado innecesariamente.
11. Tomar cultivo de la bolsa.
12. Ignorar fiebre con cálculo obstructivo.
13. Forzar líquidos en obstrucción aguda.
14. Usar AINE sin considerar función renal.

---', 98)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('fba8f987-f71d-5521-93ca-eca18e8a4180', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_99', '45. Qué memorizar', '**AKI = deterioro rápido de función renal.**

**ERC = anomalía renal ≥3 meses.**

**AKI: prerrenal / intrínseca / posrenal.**

**HiperK + ECG = emergencia.**

**Diálisis: tratar complicaciones/refractariedad, no una creatinina aislada.**

**Fístula AV: thrill/bruit; NO PA ni venopunción en ese brazo.**

**UTI baja = disuria/urgencia/frecuencia.**

**Pielonefritis = fiebre + flanco + síntomas sistémicos.**

**Sonda: solo indicada + sistema cerrado + retirar pronto.**

**Cálculo + infección/obstrucción = emergencia urológica.**

---', 99)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e16c7e0a-b165-55cf-a9f8-3aec6cbc9dd7', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_100', '46. Estado actual de guías renales en 2026', '', 100)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('79441052-a3cb-54ad-8448-fb4c2c01002c', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_101', 'CKD', '**KDIGO 2024** continúa siendo el estándar global vigente.', 101)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('3f97334c-ccb5-5f72-8e73-e0368466201d', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_102', 'AKI', 'KDIGO publicó en 2026 un **borrador para revisión pública** de una nueva guía AKI/AKD.', 102)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('57885cd5-289f-511c-a767-987a806c1815', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_103', 'Importante', 'Al momento de esta revisión, ese documento 2026 es **borrador**, no debe cargarse en la plataforma como guía final aprobada.

Para AKI se utilizan:
- principios consolidados KDIGO;
- fuentes clínicas actuales como Merck 2026;
- protocolos institucionales.

Esta distinción debe mantenerse en la trazabilidad.

---', 103)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('37d96d29-731f-5b67-b040-6ff547ba0c94', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_104', '47. Fuentes y validación', '', 104)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('db32ec58-ac67-5b08-81dd-457296117456', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_105', 'Fuente rectora', '**CICDE Panamá. Lineamientos para el Examen de Competencias de Profesionales de Enfermería, 2026.**', 105)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ecb3c912-c2d2-55cc-8f90-08f208701b1b', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_106', 'Fuentes CICDE', '**Hinkle, J. L.; Cheever, K. H. Brunner y Suddarth. Enfermería Médicoquirúrgica. 14.ª edición, 2019.**

**Potter, P. A. et al. Fundamentos de Enfermería. 11.ª edición, 2023.**', 106)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('07e460a9-3ef8-5864-84fc-d77c63b84698', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_107', 'AKI', '**Merck Manual Professional Edition. Acute Kidney Injury. Revisión completa febrero de 2026.**

**KDIGO. Acute Kidney Injury / Acute Kidney Disease update page — 2026 public-review draft status.**', 107)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ae0984c9-766e-5cbb-876f-d17672d892a8', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_108', 'CKD', '**KDIGO 2024 Clinical Practice Guideline for the Evaluation and Management of Chronic Kidney Disease.**

**Merck Manual Professional Edition. Chronic Kidney Disease. Actualizado febrero de 2026.**', 108)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5407001c-a077-56ad-b4e3-05bc3d2168d1', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_109', 'UTI', '**Infectious Diseases Society of America. 2025 Guideline Update on Complicated Urinary Tract Infections.**', 109)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('eaf9563b-b246-5539-9acf-893dbdd895cb', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_110', 'Sondaje / CAUTI', '**CDC. Guideline for Prevention of Catheter-Associated Urinary Tract Infections.**

**CDC. Clinical Safety: Preventing CAUTIs. Actualizado junio de 2025.**', 110)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8ff32846-62d0-50a1-94a8-710badd700b1', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_111', 'Urolitiasis', '**NIDDK/NIH. Kidney Stones: Definition, Diagnosis, Treatment and Prevention.**

**Merck Manual Professional Edition. Urinary Calculi. Actualizado abril de 2025.**

---', 111)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b019e529-69c6-5fed-ad12-bf3bdfff3d3f', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_112', '48. Control de calidad', 'Este paquete:
- cubre los cuatro subtemas exactos del CICDE;
- desarrolla AKI y ERC dentro de insuficiencia renal;
- utiliza KDIGO 2024 como estándar vigente de CKD;
- identifica correctamente la guía AKI 2026 como borrador;
- incorpora IDSA 2025 para UTI complicada;
- cubre prevención CAUTI;
- incluye incontinencia;
- cubre sondaje;
- incluye nefrolitiasis y obstrucción infectada;
- contiene 12 casos originales;
- evita copiar/reutilizar guías con restricciones de uso incompatibles con la futura plataforma.

---', 112)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('85d0d788-06ee-552e-a346-0994c6781a0d', '1467c643-fbc4-5413-9e29-4b59d5c9a346', 'sec_113', '49. Estado para integración', '**Estado recomendado:** `REVIEW`

Antes de `VERIFIED`:
- registrar `reviewed_by` y `reviewed_at`;
- vincular fuentes;
- mantener KDIGO AKI 2026 como `DRAFT/NOT_FINAL` hasta publicación definitiva;
- revisar normas institucionales para inserción/mantenimiento de sondas y diálisis;
- enlazar con ADULT-09 líquidos/electrolitos, ADULT-17 cardiovascular, ADULT-18 anemia y Farmacología.', 113)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('905236f1-c81e-5c42-9412-f152b9f662d0', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_1', 'Función reproductiva', '**Área:** Salud del Adulto  
**Código:** ADULT-24  
**Estado académico del paquete:** `REVIEW`  
**Última revisión del paquete:** 2026-09-10

---', 1)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('63faadc6-c928-5104-b6cb-f499bc8d6187', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_2', '1. Alcance oficial CICDE', 'El lineamiento CICDE 2026 incluye expresamente dentro de **Función reproductiva**:

1. Cáncer del cuello uterino.
2. Alteración y tratamiento de pacientes con alteraciones mamarias.
3. Aparato reproductor masculino.

Este módulo desarrolla esos tres componentes con enfoque de valoración, prevención, signos de alarma, atención de enfermería, educación y seguridad.

---', 2)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d7ed8110-8ce7-5b1b-9091-03f0bc9b1fdc', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_3', '2. Objetivos de aprendizaje', 'Al finalizar el tema, el estudiante debe poder:

1. Explicar la relación entre VPH de alto riesgo y cáncer cervicouterino.
2. Diferenciar prevención primaria, tamizaje, diagnóstico y tratamiento.
3. Reconocer signos que requieren evaluación ginecológica.
4. Conocer la actualización normativa panameña 2026 para lesiones preinvasoras del cuello uterino.
5. Valorar alteraciones mamarias frecuentes sin asumir que todo nódulo es cáncer.
6. Reconocer signos mamarios que requieren estudio.
7. Comprender principios de diagnóstico y tratamiento de cáncer de mama.
8. Aplicar cuidados de enfermería después de cirugía mamaria.
9. Explicar funciones básicas del aparato reproductor masculino.
10. Reconocer hiperplasia prostática benigna, prostatitis, cáncer de próstata y alteraciones testiculares importantes.
11. Reconocer torsión testicular como emergencia.
12. Mantener privacidad, consentimiento y comunicación respetuosa.
13. Resolver situaciones tipo examen.

---', 3)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c78acbf9-345c-5906-9663-29381c5ae29d', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_4', '3. CÁNCER DEL CUELLO UTERINO', '', 4)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('391306b3-d84a-5b02-b42c-4f126d2b8b6c', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_5', 'Concepto', 'El cáncer cervicouterino se origina en células del cuello uterino.

La infección persistente por tipos carcinogénicos del **virus del papiloma humano (VPH)** es el principal factor causal.

La mayoría de las infecciones por VPH se resuelven espontáneamente; solo una proporción persiste y puede progresar a lesiones precancerosas y cáncer.

---', 5)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9ecfecda-ed41-52d4-91c3-789b0fd2f710', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_6', '4. Prevención primaria', 'Incluye:

- vacunación contra VPH;
- educación;
- reducción de exposición al tabaco;
- prácticas sexuales más seguras;
- acceso a servicios de salud.', 6)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('815b69e6-5076-599c-ad86-80a416fba4c4', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_7', 'Vacunación', 'La vacunación previene infecciones por tipos de VPH responsables de gran parte de los cánceres cervicouterinos.

Para la plataforma deben utilizarse las edades, dosis y grupos especiales del **Esquema Nacional de Vacunación de Panamá 2026**, no copiar esquemas de otros países como si fueran nacionales.

---', 7)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('19fe5567-0791-5553-854f-5c487af01f23', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_8', '5. Tamizaje cervicouterino', 'El tamizaje busca detectar infección de alto riesgo o lesiones precursoras antes de que aparezca cáncer invasor.

Métodos utilizados según programa:

- pruebas de VPH de alto riesgo;
- citología cervical/Papanicolaou;
- estrategias de triage;
- inspección visual en algunos sistemas.', 8)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('02010655-45ff-5862-9870-51b11f0e0326', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_9', 'Diferencia clave', '**Tamizaje no equivale a diagnóstico definitivo.**

Una prueba positiva requiere el seguimiento indicado.

---', 9)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a185d239-5073-5d18-a667-996477ba8328', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_10', '6. Actualización OMS 2026', 'La OMS publicó en mayo de 2026 una guía específica sobre **genotipificación de ADN del VPH** para apoyar la estratificación de riesgo después de una prueba positiva.

En julio de 2026 publicó además orientación de implementación de programas de tamizaje basados en VPH.', 10)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2361ba67-c5e5-5fb9-be33-058b1e7f340e', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_11', 'Principio', 'La tendencia internacional es fortalecer pruebas de VPH de alto rendimiento, pero cada país adapta:
- edades;
- intervalos;
- triage;
- seguimiento;
- recursos.

---', 11)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('cdde5818-0b51-5432-8101-30aea50ba63d', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_12', '7. Panamá — norma actualizada en 2026', 'MINSA publicó la:

**Resolución N.º 546 de 24 de julio de 2026**, que aprueba las **Normas Técnico Administrativas del Programa de Prevención y Detección de Lesiones Preinvasoras de Cáncer del Cuello Uterino y Guías de Manejo**.', 12)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('042b2575-f768-52e6-be19-8eae135a31bf', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_13', 'Importancia para la plataforma', 'Esta resolución es una fuente nacional actual y debe prevalecer para conductas operativas panameñas sobre documentos antiguos cuando exista diferencia.

MINSA también mantiene en 2026 una estrategia nacional de fortalecimiento de:
- prevención;
- vacunación;
- citología;
- diagnóstico oportuno;
- reducción de mora de resultados.

---', 13)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ee176dca-f91a-5b91-9182-8dc1a8c89860', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_14', '8. Manifestaciones que requieren evaluación', 'El precáncer puede ser asintomático.

Cáncer invasor puede producir:

- sangrado vaginal anormal;
- sangrado postcoital;
- sangrado después de menopausia;
- secreción vaginal anormal;
- dolor pélvico;
- dolor durante relaciones sexuales;
- síntomas urinarios/intestinales en enfermedad avanzada.', 14)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('0c266e6d-5ed1-510c-bfaf-cee1bee25eaa', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_15', 'Clave', 'No esperar síntomas para realizar prevención/tamizaje.

---', 15)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c71081c4-8492-5702-b910-5c24c6968fb4', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_16', '9. Diagnóstico', 'Después de un tamizaje anormal pueden utilizarse:

- colposcopia;
- biopsia;
- procedimientos diagnósticos adicionales.

El diagnóstico de cáncer requiere confirmación histológica.

---', 16)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a7a4b491-f2d6-57a1-a184-0c459f975270', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_17', '10. Tratamiento cervicouterino', 'Depende de:

- lesión precursora vs cáncer;
- estadio;
- deseo reproductivo;
- edad;
- comorbilidades;
- recursos.

Puede incluir:

- ablación o escisión de lesiones precursoras;
- conización;
- cirugía;
- radioterapia;
- quimioterapia;
- terapias sistémicas en enfermedad avanzada.

---', 17)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('886608c5-c495-5ccd-9df4-a36f72dadf5d', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_18', '11. Cuidados de enfermería', '- educación preprocedimiento;
- consentimiento;
- control de dolor;
- vigilancia de sangrado;
- prevención de infección;
- apoyo emocional;
- sexualidad/fertilidad;
- seguimiento;
- adherencia a citas.', 18)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('125afe74-0cf5-587d-82c6-fdfa17d6d4fd', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_19', 'Alarma posterior a procedimiento', '- sangrado abundante;
- fiebre;
- dolor creciente;
- secreción maloliente;
- síncope.

---', 19)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9ec94cce-d82b-5698-955e-0c0f343c0a0c', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_20', '12. ALTERACIONES MAMARIAS', '', 20)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('c9aa05f0-2a08-5e21-acf9-95e9312b4cd7', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_21', 'Principio', 'La mayoría de los cambios mamarios no son cáncer, pero cualquier cambio nuevo o persistente debe evaluarse adecuadamente.

NCI enfatiza que muchas alteraciones benignas pueden producir nódulos o cambios en la mamografía.

---', 21)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e99c69ab-45f0-56a6-a0d4-7b782cf3b2fc', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_22', '13. Valoración mamaria', 'Preguntar:

- inicio;
- dolor;
- relación con ciclo;
- masa;
- secreción;
- embarazo/lactancia;
- trauma;
- infección;
- medicamentos;
- antecedentes personales;
- antecedentes familiares;
- cirugía previa.

Observar/palpar según contexto:

- simetría;
- piel;
- pezón;
- retracción;
- eritema;
- edema;
- masa;
- ganglios.

---', 22)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6c9a8844-85c2-5e2a-90c3-058305bc9f53', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_23', '14. Cambios benignos frecuentes', 'Pueden incluir:

- quistes;
- fibroadenoma;
- cambios fibroquísticos;
- ectasia ductal;
- necrosis grasa;
- mastitis;
- otras lesiones benignas.', 23)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('980f4878-0447-50b0-98c8-8361fcb5374b', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_24', 'Clave', '“Benigno” no debe asignarse solo por palpación; el diagnóstico requiere evaluación apropiada.

---', 24)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('16b7abd4-eec8-5bcc-bc85-fe24b686d7fd', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_25', '15. Signos mamarios de alarma', '- masa nueva persistente;
- retracción del pezón;
- secreción sanguinolenta;
- piel tipo “naranja”;
- ulceración;
- cambio focal persistente;
- adenopatía;
- engrosamiento;
- edema unilateral;
- alteraciones inflamatorias persistentes.

Estos signos no confirman cáncer por sí solos, pero requieren evaluación.

---', 25)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('71b3f8e0-28f4-5e6b-a746-e722dce51728', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_26', '16. Diagnóstico de alteraciones mamarias', 'Puede integrar:

- examen clínico;
- mamografía;
- ultrasonido;
- resonancia en pacientes seleccionadas;
- biopsia.', 26)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('5f07115b-2623-5e9b-9e5a-84dfb2567844', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_27', 'Principio triple', 'La interpretación debe integrar clínica + imagen + patología cuando corresponde.

---', 27)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('fc5a2ae1-3d96-514b-a70b-a5c03431f818', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_28', '17. Cáncer de mama', 'El tratamiento depende de:

- tipo;
- estadio;
- receptores hormonales;
- HER2;
- características moleculares;
- estado general.

Puede incluir:

- cirugía conservadora;
- mastectomía;
- biopsia/ganglio centinela;
- radioterapia;
- quimioterapia;
- terapia endocrina;
- terapia anti-HER2;
- inmunoterapia u otras terapias dirigidas.

---', 28)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2bd60c81-c1ad-585b-8a70-f138fc91be23', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_29', '18. Cuidados postoperatorios de mama', '- dolor;
- herida;
- drenajes;
- movilidad;
- signos de infección;
- sensibilidad;
- imagen corporal;
- apoyo emocional;
- educación.

Tras cirugía axilar puede existir riesgo de linfedema.', 29)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('f1e7335e-1fba-512b-a7ca-fefb6c990053', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_30', 'Prevención/educación', '- vigilar aumento de volumen;
- proteger piel;
- prevenir infecciones;
- ejercicio progresivo indicado;
- informar sensación de pesadez/tensión.

Las restricciones absolutas históricas sobre presión arterial o venopunción del brazo deben individualizarse según riesgo, protocolo y alternativas, evitando afirmaciones rígidas sin evidencia.

---', 30)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('a41eba95-c62c-55de-8946-95f86d4f8c57', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_31', '19. Mastitis', 'Frecuente durante lactancia, aunque puede aparecer fuera de ella.

Puede causar:

- dolor;
- eritema;
- calor;
- edema;
- fiebre.

Evaluar:
- lactancia;
- absceso;
- respuesta al tratamiento;
- signos sistémicos.

En lactancia, el vaciamiento efectivo de la mama suele formar parte del manejo cuando es seguro y apropiado.

---', 31)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('6c51251d-6420-5950-9dda-a5c73255787e', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_32', '20. APARATO REPRODUCTOR MASCULINO', 'Incluye:

- testículos;
- epidídimo;
- conductos deferentes;
- vesículas seminales;
- próstata;
- pene;
- estructuras asociadas.

Funciones:
- producción de espermatozoides;
- secreción hormonal;
- transporte de semen;
- función sexual/reproductiva.

---', 32)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('abe049fc-9e4f-5f1f-9b9d-082435d780a7', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_33', '21. Valoración masculina', 'Preguntar:

- síntomas urinarios;
- dolor;
- masa;
- cambios testiculares;
- secreción;
- lesiones;
- función sexual;
- fertilidad;
- medicamentos;
- ITS;
- antecedentes urológicos.

Mantener privacidad y lenguaje clínico sin prejuicios.

---', 33)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('49a0a1ad-784e-5e8f-bb28-6c8265f1f686', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_34', '22. Hiperplasia prostática benigna (HPB)', 'Es un crecimiento no maligno de la próstata frecuente con la edad.

Síntomas del tracto urinario inferior:

- chorro débil;
- dificultad para iniciar;
- intermitencia;
- vaciamiento incompleto;
- frecuencia;
- urgencia;
- nocturia.', 34)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ee6f29fa-553f-5044-b819-725ad3772e3b', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_35', 'Complicaciones', '- retención aguda;
- UTI;
- cálculos vesicales;
- deterioro renal en casos severos.

---', 35)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4c7f83e3-1a0e-56ba-a9d4-ec4dcd493ca4', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_36', '23. Tratamiento de HPB', 'Según severidad y preferencias:

- observación;
- modificación de hábitos;
- alfa-bloqueadores;
- inhibidores de 5-alfa-reductasa;
- otros tratamientos;
- procedimientos/cirugía.', 36)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('001d3799-b88e-5d61-8eb0-4cade3e63818', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_37', 'Enfermería', 'Con alfa-bloqueadores vigilar:
- mareo;
- hipotensión ortostática;
- riesgo de caídas.

---', 37)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1cbce411-cf0d-569c-ba93-d26566626c22', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_38', '24. Retención urinaria aguda', 'Puede producir:

- dolor suprapúbico;
- distensión;
- incapacidad de orinar;
- inquietud.

Requiere drenaje y evaluación de causa.

---', 38)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('b5e92e37-397c-5a3b-9283-d0131f09712d', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_39', '25. Prostatitis', 'Puede ser:

- bacteriana aguda;
- bacteriana crónica;
- síndrome de dolor pélvico crónico.

Prostatitis bacteriana aguda puede producir:

- fiebre;
- escalofríos;
- disuria;
- urgencia;
- dolor perineal;
- malestar.', 39)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e79c8177-0e5f-51f5-b8be-c286a20357c2', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_40', 'Seguridad', 'En sospecha de prostatitis aguda, evitar masaje prostático vigoroso por riesgo de bacteriemia.

---', 40)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('94dbce5f-a458-5e13-8a41-b1e437a1f515', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_41', '26. Cáncer de próstata', 'Puede ser asintomático durante etapas tempranas.

La detección puede involucrar:

- PSA;
- examen clínico;
- resonancia;
- biopsia.', 41)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ea1c699a-b275-573c-8830-f7dcc14e9358', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_42', 'Importante', 'PSA elevado **no significa automáticamente cáncer**; puede elevarse por otras condiciones.

La decisión de tamizaje debe ser compartida según edad, riesgo, expectativas de vida y recomendaciones nacionales/internacionales vigentes.

---', 42)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2a808fba-e06c-53ee-adff-962c99c06829', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_43', '27. Tratamiento de cáncer de próstata', 'Puede incluir:

- vigilancia activa;
- cirugía;
- radioterapia;
- terapia de privación androgénica;
- quimioterapia;
- terapias dirigidas;
- otros tratamientos.

Efectos que requieren apoyo:
- incontinencia;
- disfunción eréctil;
- síntomas urinarios;
- fatiga;
- cambios óseos/metabólicos con terapia hormonal.

---', 43)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('8eec3091-78a8-5f28-9540-766f8482ee5a', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_44', '28. Torsión testicular', 'Es torsión del cordón espermático con compromiso de perfusión.

Manifestaciones:

- dolor testicular súbito intenso;
- edema;
- náuseas/vómitos;
- testículo elevado/anormalmente orientado.', 44)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('64aa092c-a6bb-5be0-8680-ec3453da2549', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_45', 'Prioridad absoluta', '**Es una emergencia quirúrgica dependiente del tiempo.**

No retrasar valoración por estudios innecesarios cuando la sospecha clínica es alta.

---', 45)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('90659b29-ee76-5724-b22f-0cf4e6336582', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_46', '29. Epididimitis', 'Puede producir:

- dolor escrotal más gradual;
- edema;
- síntomas urinarios;
- fiebre;
- riesgo de ITS según contexto.

Debe diferenciarse de torsión.', 46)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e8819f42-c95f-5e2f-9da9-6ed578e3ef9d', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_47', 'Clave', 'En dolor testicular agudo, primero excluir torsión.

---', 47)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e2f8dc96-8de2-57f1-8b68-e002fde64627', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_48', '30. Cáncer testicular', 'Puede manifestarse con:

- masa testicular indolora;
- aumento de tamaño;
- sensación de peso;
- dolor en algunos casos.

Una masa intratesticular nueva requiere evaluación rápida.

---', 48)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('024fa581-e36f-51a5-b386-bf6fe4d02ba2', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_49', '31. Disfunción eréctil', 'Puede asociarse con:

- diabetes;
- enfermedad vascular;
- medicamentos;
- factores psicológicos;
- trastornos hormonales;
- cirugía pélvica.', 49)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('3aa7458b-dc63-5a1e-bb01-241eae5b18f8', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_50', 'Seguridad farmacológica', 'Los inhibidores PDE-5 no deben combinarse con nitratos por riesgo de hipotensión grave.

---', 50)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e626f827-78ec-5a08-97bf-3e49416ae6bd', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_51', '32. Fertilidad y sexualidad', 'La atención debe reconocer:

- deseo reproductivo;
- imagen corporal;
- función sexual;
- efectos del cáncer/tratamiento;
- anticoncepción;
- ITS;
- preservación de fertilidad.

No asumir que una persona adulta no desea información sexual o reproductiva.

---', 51)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('96008855-f3d3-5fbf-aa77-e6854536a146', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_52', '33. PAE', '', 52)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('49576fcb-491c-5941-aafe-24adb6e12c5b', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_53', 'Valoración', '- síntomas;
- sangrado;
- dolor;
- masa;
- función sexual;
- función urinaria;
- antecedentes;
- impacto emocional.', 53)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('e5f17e5e-1a15-5133-b778-92ba8be3e13f', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_54', 'Diagnóstico/juicio', '- dolor;
- alteración de eliminación;
- ansiedad;
- riesgo de infección;
- imagen corporal;
- conocimiento.', 54)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('9fe78681-3815-5bf2-9d72-23067f168b06', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_55', 'Planificación', 'Priorizar:
- hemorragia;
- sepsis;
- torsión testicular;
- retención;
- cáncer con complicaciones;
- continuidad del seguimiento.', 55)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('96dd7f99-9413-5a13-82dc-e7534afbd76f', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_56', 'Implementación', '- educación;
- vigilancia;
- medicación prescrita;
- cuidados de herida;
- apoyo;
- derivación.', 56)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('ba154635-f518-5d9f-993a-f7c429b683a5', '22fd6ec7-8930-5ef4-b6f7-acb9d26ee87f', 'sec_57', 'Evaluación', '- síntomas;
- función;
- comprensión;
- adherencia;
- complicaciones.

---', 57)
