INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('421fc6c1-1a95-5723-904f-857d804ba587', '8f08d277-84e4-510d-b5cd-d41106dc7afe', 'sec_9', 'D — Disability', 'Estado neurológico.', 9)
