INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('2e28a75d-dd68-54e8-8966-e1e7cb06364e', '8f08d277-84e4-510d-b5cd-d41106dc7afe', 'sec_10', 'E — Exposure', 'Exponer para evaluar extensión, pero **prevenir hipotermia**.', 10)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('d790ed72-3bf6-5ac6-a46b-986db5d065fe', '8f08d277-84e4-510d-b5cd-d41106dc7afe', 'sec_11', 'Clave', 'Una quemadura muy visible no debe distraer de amenazas vitales o trauma concomitante.

---', 11)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('fb380652-08fd-50f8-a1ea-5260f529cbdd', '8f08d277-84e4-510d-b5cd-d41106dc7afe', 'sec_12', '5. Detener el proceso de quemadura', '- retirar al paciente de la fuente;
- apagar llamas;
- retirar ropa caliente/no adherida;
- retirar joyas/relojes tempranamente;
- enfriar la quemadura térmica con agua corriente fresca;
- evitar hielo;
- cubrir posteriormente;
- prevenir hipotermia.', 12)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('1a62c8d9-c2a4-5477-bf03-034feb4d0e2d', '8f08d277-84e4-510d-b5cd-d41106dc7afe', 'sec_13', 'Primeros auxilios', 'Fuentes actuales como ABA/NHS recomiendan enfriamiento con **agua corriente fresca, no helada**, frecuentemente alrededor de 20 minutos cuando es factible y sin provocar hipotermia.', 13)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('72ddc84b-e655-5649-8253-a69f1de39182', '8f08d277-84e4-510d-b5cd-d41106dc7afe', 'sec_14', 'Nunca', '- mantequilla;
- aceite;
- pasta dental;
- hielo directo;
