INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('43a69a43-51db-52b5-b5cd-2aa19114c8b1', '8f08d277-84e4-510d-b5cd-d41106dc7afe', 'sec_16', 'Superficial', '- epidermis;
