INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('06647765-20e8-55d9-a7a6-1672c31d5018', '76de872e-9cd4-5576-bbd6-6bebebed9423', 'sec_121', 'Fuentes CICDE', '**Hinkle, J. L.; Cheever, K. H. Brunner y Suddarth. Enfermería Médicoquirúrgica. 14.ª edición, 2019.**

