INSERT INTO public.lesson_sections (id, lesson_id, section_key, title, body, sort_order)
VALUES ('4a0a3e9c-c2b5-57fb-91db-62deb89c7858', '76de872e-9cd4-5576-bbd6-6bebebed9423', 'sec_122', 'Triage/emergencias', '**World Health Organization. Interagency Integrated Triage Tool (IITT).**

**WHO/ICRC. Basic Emergency Care: approach to the acutely ill and injured.**

**WHO Emergency Care Toolkit.**', 122)
ON CONFLICT (lesson_id, section_key) DO NOTHING;
